// ==========================================
// V7 - Multi-Student Class Management System
// ==========================================

var V7_STORAGE_KEYS = {
  CLASSES: "ctp_classes",
  STUDENTS: "ctp_students",
  CURRENT_STUDENT: "ctp_current_student",
  DATA_PREFIX: "ctp_data_"
};

function v7GetClasses() {
  var saved = localStorage.getItem(V7_STORAGE_KEYS.CLASSES);
  if (saved) {
    try { return JSON.parse(saved); } catch(e) {}
  }
  return ["Class A", "Class B", "Class C"];
}

function v7SaveClasses(classes) {
  localStorage.setItem(V7_STORAGE_KEYS.CLASSES, JSON.stringify(classes));
}

function v7GetStudents() {
  var saved = localStorage.getItem(V7_STORAGE_KEYS.STUDENTS);
  if (saved) {
    try { return JSON.parse(saved); } catch(e) {}
  }
  return {};
}

function v7SaveStudents(students) {
  localStorage.setItem(V7_STORAGE_KEYS.STUDENTS, JSON.stringify(students));
}

function v7GetCurrentStudentId() {
  return localStorage.getItem(V7_STORAGE_KEYS.CURRENT_STUDENT);
}

function v7SetCurrentStudentId(id) {
  if (id) {
    localStorage.setItem(V7_STORAGE_KEYS.CURRENT_STUDENT, id);
  } else {
    localStorage.removeItem(V7_STORAGE_KEYS.CURRENT_STUDENT);
  }
}

function v7GetStudentDataKey(studentId) {
  return V7_STORAGE_KEYS.DATA_PREFIX + studentId;
}

function v7LoadStudentData(studentId) {
  var key = v7GetStudentDataKey(studentId);
  var saved = localStorage.getItem(key);
  if (saved) {
    try { return JSON.parse(saved); } catch(e) {}
  }
  return null;
}

function v7SaveStudentData(studentId, data) {
  var key = v7GetStudentDataKey(studentId);
  localStorage.setItem(key, JSON.stringify(data));
}

function v7InitDemoData() {
  // Initialize demo data on first run
  var students = v7GetStudents();
  var classes = v7GetClasses();
  
  if (Object.keys(students).length > 0) return; // already initialized
  
  // Demo accounts
  var demoStudents = {
    "stu_001": {
      studentId: "stu_001", name: "Alex Johnson", password: "123456",
      classId: "Class A", createdAt: Date.now()
    },
    "stu_002": {
      studentId: "stu_002", name: "Maria Chen", password: "123456",
      classId: "Class A", createdAt: Date.now()
    },
    "stu_003": {
      studentId: "stu_003", name: "James Wilson", password: "123456",
      classId: "Class B", createdAt: Date.now()
    }
  };
  
  v7SaveStudents(demoStudents);
  v7SaveClasses(classes);
}

function switchAuthTab(tab) {
  var loginTab = document.getElementById("authTabLogin");
  var registerTab = document.getElementById("authTabRegister");
  var loginForm = document.getElementById("loginForm");
  var registerForm = document.getElementById("registerForm");
  var loginHint = document.getElementById("loginHint");
  var regHint = document.getElementById("regHint");
  
  if (loginHint) loginHint.textContent = "";
  if (regHint) regHint.textContent = "";
  
  if (tab === "login") {
    loginTab.classList.add("active");
    registerTab.classList.remove("active");
    loginForm.style.display = "block";
    registerForm.style.display = "none";
    setTimeout(function(){ document.getElementById("loginStudentId").focus(); }, 50);
  } else {
    loginTab.classList.remove("active");
    registerTab.classList.add("active");
    loginForm.style.display = "none";
    registerForm.style.display = "block";
    // Update class dropdown
    updateClassDropdown();
    setTimeout(function(){ document.getElementById("regClass").focus(); }, 50);
  }
}

function updateClassDropdown() {
  var sel = document.getElementById("regClass");
  if (!sel) return;
  var classes = v7GetClasses();
  // Keep custom option
  var customOpt = sel.querySelector('option[value="__custom__"]');
  var customHtml = customOpt ? customOpt.outerHTML : '';
  
  var html = '';
  for (var i = 0; i < classes.length; i++) {
    html += '<option value="' + classes[i] + '">' + classes[i] + '</option>';
  }
  html += customHtml;
  sel.innerHTML = html;
}

function showAuthOverlay() {
  var overlay = document.getElementById("authOverlay");
  if (overlay) overlay.style.display = "flex";
  var app = document.querySelector(".app-container");
  if (app) app.style.display = "none";
  var ws = document.getElementById("welcomeScreen");
  if (ws) ws.style.display = "none";
}

function hideAuthOverlay() {
  var overlay = document.getElementById("authOverlay");
  if (overlay) overlay.style.display = "none";
  var app = document.querySelector(".app-container");
  if (app) app.style.display = "flex";
}

function loginStudent() {
  var studentId = document.getElementById("loginStudentId").value.trim();
  var password = document.getElementById("loginPassword").value;
  var hint = document.getElementById("loginHint");
  
  if (!studentId) { hint.textContent = "Please enter your Student ID"; return; }
  if (!password) { hint.textContent = "Please enter your password"; return; }
  
  var students = v7GetStudents();
  var stu = students[studentId];
  
  if (!stu) {
    hint.textContent = "Student ID not found. Please register first.";
    return;
  }
  if (stu.password !== password) {
    hint.textContent = "Incorrect password.";
    return;
  }
  
  // Login success
  v7SetCurrentStudentId(studentId);
  loadStudentDataV7(studentId);
  hideAuthOverlay();
  updateStudentInfoUI();
  navigateTo("dashboard");
}

function registerStudentV7() {
  var classSelect = document.getElementById("regClass");
  var classCustom = document.getElementById("regClassCustom");
  var studentId = document.getElementById("regStudentId").value.trim();
  var name = document.getElementById("regName").value.trim();
  var password = document.getElementById("regPassword").value;
  var confirmPassword = document.getElementById("regConfirmPassword").value;
  var hint = document.getElementById("regHint");
  
  var className = classSelect.value;
  if (className === "__custom__") {
    className = classCustom.value.trim();
    if (!className) { hint.textContent = "Please enter a class name"; return; }
  }
  
  if (!studentId) { hint.textContent = "Please enter your Student ID"; return; }
  if (!name) { hint.textContent = "Please enter your name"; return; }
  if (!password) { hint.textContent = "Please enter a password"; return; }
  if (password.length < 4) { hint.textContent = "Password must be at least 4 characters"; return; }
  if (password !== confirmPassword) { hint.textContent = "Passwords do not match"; return; }
  
  var students = v7GetStudents();
  if (students[studentId]) {
    hint.textContent = "Student ID already exists. Please login instead.";
    return;
  }
  
  // Add class to classes list if new
  var classes = v7GetClasses();
  if (classes.indexOf(className) === -1) {
    classes.push(className);
    v7SaveClasses(classes);
  }
  
  // Create student account
  students[studentId] = {
    studentId: studentId,
    name: name,
    password: password,
    classId: className,
    createdAt: Date.now()
  };
  v7SaveStudents(students);
  
  // Initialize student data
  var newStudentData = createNewStudent(name, className);
  newStudentData.id = studentId;
  newStudentData.classCode = className;
  v7SaveStudentData(studentId, newStudentData);
  
  // Auto login
  v7SetCurrentStudentId(studentId);
  loadStudentDataV7(studentId);
  
  hint.textContent = "";
  hideAuthOverlay();
  updateStudentInfoUI();
  navigateTo("dashboard");
}

function logoutStudentV7() {
  if (!confirm("Are you sure you want to log out?")) return;
  
  // Save current state before logout
  saveStudentV7();
  saveMessagesV7();
  saveAIConversationV7();
  
  v7SetCurrentStudentId(null);
  AppState.student = null;
  AppState.messages = [];
  AppState.aiConversation = [];
  AI_TUTOR_STATE.conversation = [];
  
  showAuthOverlay();
  switchAuthTab("login");
}

function loadStudentDataV7(studentId) {
  var data = v7LoadStudentData(studentId);
  var students = v7GetStudents();
  var stuInfo = students[studentId];
  
  if (!data) {
    // Create fresh data
    data = createNewStudent(stuInfo ? stuInfo.name : "Student", stuInfo ? stuInfo.classId : "Class A");
    data.id = studentId;
    data.classCode = stuInfo ? stuInfo.classId : "Class A";
    v7SaveStudentData(studentId, data);
  }
  
  // Defensive checks (same as loadStudent)
  if (!Array.isArray(data.questionHistory)) data.questionHistory = [];
  if (!data.dimensionScores) data.dimensionScores = {};
  if (!data.dimensionAttempts) data.dimensionAttempts = {};
  var _dims = ['clarity','precision','accuracy','relevance','consistency','logicalCorrectness','completeness','fairness'];
  _dims.forEach(function(d) {
    if (data.dimensionScores[d] === undefined) data.dimensionScores[d] = 0;
    if (data.dimensionAttempts[d] === undefined) data.dimensionAttempts[d] = 0;
  });
  if (!data.pblProjects) data.pblProjects = getDefaultPBLProjects();

  if (!data.milestones) data.milestones = null;
  if (!data.capstoneProjectId) data.capstoneProjectId = null;
  if (!data.capstoneSelected) data.capstoneSelected = false;

  ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8'].forEach(function(ch) {
    if (!data.pblProjects[ch]) data.pblProjects[ch] = getDefaultPBLProjects()[ch];
    if (!data.pblProjects[ch].knowledgeMap || !data.pblProjects[ch].knowledgeMap.nodes || data.pblProjects[ch].knowledgeMap.nodes.length === 0) {
      data.pblProjects[ch].knowledgeMap = getDefaultKnowledgeMap(ch);
    }
  });
  // Ensure name from account info
  if (stuInfo) data.name = stuInfo.name;
  
  AppState.student = data;
  
  // Load messages
  var msgKey = v7GetStudentDataKey(studentId) + "_messages";
  var savedMsgs = localStorage.getItem(msgKey);
  if (savedMsgs) {
    try { AppState.messages = JSON.parse(savedMsgs); } catch(e) {
      AppState.messages = getDefaultMessagesV7();
    }
  } else {
    AppState.messages = getDefaultMessagesV7();
  }
  
  // Load AI conversation
  var aiKey = v7GetStudentDataKey(studentId) + "_ai_conv";
  var savedAI = localStorage.getItem(aiKey);
  AI_TUTOR_STATE.conversation = [];
  if (savedAI) {
    try { AI_TUTOR_STATE.conversation = JSON.parse(savedAI); } catch(e) {}
  }
  if (AI_TUTOR_STATE.conversation.length === 0) {
    AI_TUTOR_STATE.conversation.push({
      role: "ai", text: "Hi! I'm your AI Critical Thinking Tutor. I'm here to help you think through problems, not just give you answers. What would you like to work on today?", type: "greeting"
    });
  }
}

function getDefaultMessagesV7() {
  return [
    {
      id: "msg_welcome",
      type: "info",
      title: "Welcome to Critical Thinking!",
      body: "Welcome to the Critical Thinking Learning Platform. Start by taking the pretest to assess your current level, then work through the chapters at your own pace. Your AI tutor is available 24/7 to guide your thinking!",
      time: Date.now(),
      read: false
    }
  ];
}

function saveStudentV7() {
  var sid = v7GetCurrentStudentId();
  if (sid && AppState.student) {
    v7SaveStudentData(sid, AppState.student);
  }
}

function saveMessagesV7() {
  var sid = v7GetCurrentStudentId();
  if (sid && AppState.messages) {
    var msgKey = v7GetStudentDataKey(sid) + "_messages";
    localStorage.setItem(msgKey, JSON.stringify(AppState.messages));
  }
}

function saveAIConversationV7() {
  var sid = v7GetCurrentStudentId();
  if (sid && AI_TUTOR_STATE.conversation) {
    var aiKey = v7GetStudentDataKey(sid) + "_ai_conv";
    localStorage.setItem(aiKey, JSON.stringify(AI_TUTOR_STATE.conversation));
  }
}

function updateStudentInfoUI() {
  var s = AppState.student;
  var students = v7GetStudents();
  var sid = v7GetCurrentStudentId();
  var stuInfo = students[sid];
  var className = stuInfo ? stuInfo.classId : (s ? s.classCode : "—");
  
  var nameEl = document.getElementById("studentName");
  if (nameEl && s) nameEl.textContent = s.name;
  
  var avatarEl = document.getElementById("studentAvatar");
  if (avatarEl && s) avatarEl.textContent = s.name.charAt(0).toUpperCase();
  
  var topNameEl = document.getElementById("topbarUserName");
  if (topNameEl && s) topNameEl.textContent = s.name;
  
  var topClassEl = document.getElementById("topbarClassBadge");
  if (topClassEl) topClassEl.textContent = className;
  
  var roleEl = document.getElementById("studentRole");
  if (roleEl && stuInfo) roleEl.textContent = stuInfo.studentId;
}

// Setup class custom input toggle
function setupClassSelectToggle() {
  var sel = document.getElementById("regClass");
  var customInput = document.getElementById("regClassCustom");
  if (!sel || !customInput) return;
  sel.addEventListener("change", function() {
    if (sel.value === "__custom__") {
      customInput.style.display = "block";
      customInput.focus();
    } else {
      customInput.style.display = "none";
    }
  });
}


