function openRegisterModal() {
  document.getElementById("registerModal").classList.remove("hidden");
  document.getElementById("regName").focus();
}

function closeRegisterModal() {
  document.getElementById("registerModal").classList.add("hidden");
}

function registerStudent() {
  var name = document.getElementById("regName").value.trim();
  var code = document.getElementById("regCode").value.trim();
  var hint = document.getElementById("regHint");
  
  if (!name) {
    hint.textContent = "Please enter your name";
    return;
  }
  if (!code) {
    hint.textContent = "Please enter the class code";
    return;
  }
  if (VALID_CLASS_CODES.indexOf(code) === -1) {
    hint.textContent = "Invalid class code. Please check with your teacher.";
    return;
  }
  
  // Create new student
  var newStudent = createNewStudent(name, code);
  AppState.student = newStudent;
  saveStudent();
  saveMessages();
  
  // Update UI
  document.getElementById("studentName").textContent = name;
  document.getElementById("studentAvatar").textContent = name.charAt(0).toUpperCase();
  
  closeRegisterModal();
  hideWelcomeScreen();
  navigateTo("dashboard");
}

