function getDefaultKnowledgeMap(chKey) {
  var nodes = [];
  var links = [];
  var W = 700, H = 450;
  
  if (chKey === 'ch1') {
    var cx = W/2, cy = H/2, r = 140;
    nodes.push({ id: 'ct_main', text: 'Critical Thinking', x: cx, y: cy, isMain: true });
    var ch1Concepts = [
      { id: 'standards', text: 'CT Standards', angle: 0 },
      { id: 'clarity', text: 'Clarity', angle: Math.PI/4 },
      { id: 'accuracy', text: 'Accuracy', angle: Math.PI/2 },
      { id: 'benefits', text: 'Benefits', angle: 3*Math.PI/4 },
      { id: 'barriers', text: 'Barriers', angle: Math.PI },
      { id: 'thinker', text: 'CT Thinker', angle: 5*Math.PI/4 },
      { id: 'logic', text: 'Logical Correctness', angle: 3*Math.PI/2 },
      { id: 'fairness', text: 'Fairness', angle: 7*Math.PI/4 }
    ];
    ch1Concepts.forEach(function(c) {
      nodes.push({ id: c.id, text: c.text, x: cx + r*Math.cos(c.angle-Math.PI/2), y: cy + r*Math.sin(c.angle-Math.PI/2) });
      links.push({ from: 'ct_main', to: c.id, label: 'includes' });
    });
    links.push({ from: 'standards', to: 'clarity', label: 'is a standard' });
    links.push({ from: 'standards', to: 'accuracy', label: 'is a standard' });
    links.push({ from: 'standards', to: 'logic', label: 'is a standard' });
    links.push({ from: 'standards', to: 'fairness', label: 'is a standard' });
    links.push({ from: 'barriers', to: 'thinker', label: 'opposed by' });
  } else {
    var cx = W/2;
    nodes.push({ id: 'arg_main', text: 'Arguments', x: cx, y: 50, isMain: true });
    nodes.push({ id: 'premises', text: 'Premises', x: cx-160, y: 170 });
    nodes.push({ id: 'conclusions', text: 'Conclusions', x: cx+160, y: 170 });
    links.push({ from: 'arg_main', to: 'premises', label: 'contains' });
    links.push({ from: 'arg_main', to: 'conclusions', label: 'supports' });
    links.push({ from: 'premises', to: 'conclusions', label: 'support' });
    var nonArgs = [
      { id: 'reports', text: 'Reports', x: cx-220, y: 300 },
      { id: 'unsupported', text: 'Unsupported Assertions', x: cx-70, y: 300 },
      { id: 'conditional', text: 'Conditional Statements', x: cx+80, y: 300 },
      { id: 'explanations', text: 'Explanations', x: cx+230, y: 300 }
    ];
    nonArgs.forEach(function(n) {
      nodes.push(n);
      links.push({ from: 'arg_main', to: n.id, label: 'is not' });
    });
    nodes.push({ id: 'illustrations', text: 'Illustrations', x: cx, y: 410 });
    links.push({ from: 'arg_main', to: 'illustrations', label: 'is not' });
  }
  
  return { nodes: nodes, links: links };
}function getDefaultKnowledgeMap(chKey) {
  var concepts = [];
  var links = [];
  if (chKey === 'ch1') {
    concepts = [
      { label: 'Critical Thinking', core: true },
      { label: 'Clarity', core: false },
      { label: 'Accuracy', core: false },
      { label: 'Precision', core: false },
      { label: 'Relevance', core: false },
      { label: 'Logical Correctness', core: false },
      { label: 'Fairness', core: false },
      { label: 'Barriers to Thinking', core: false }
    ];
    links = [
      { from: 0, to: 1, label: 'requires' },
      { from: 0, to: 2, label: 'requires' },
      { from: 0, to: 3, label: 'requires' },
      { from: 0, to: 4, label: 'requires' },
      { from: 0, to: 5, label: 'requires' },
      { from: 0, to: 7, label: 'is hindered by' },
      { from: 1, to: 2, label: 'supports' },
      { from: 2, to: 5, label: 'enables' }
    ];
  } else {
    concepts = [
      { label: 'Argument', core: true },
      { label: 'Premise', core: false },
      { label: 'Conclusion', core: false },
      { label: 'Indicator Words', core: false },
      { label: 'Conditional Statement', core: false },
      { label: 'Appeal to Authority', core: false },
      { label: 'Rhetoric', core: false },
      { label: 'Fallacy', core: false }
    ];
    links = [
      { from: 0, to: 1, label: 'contains' },
      { from: 0, to: 2, label: 'contains' },
      { from: 1, to: 3, label: 'signaled by' },
      { from: 2, to: 3, label: 'signaled by' },
      { from: 0, to: 4, label: 'may include' },
      { from: 5, to: 6, label: 'is a type of' },
      { from: 6, to: 0, label: 'is not an' },
      { from: 7, to: 0, label: 'flaws an' }
    ];
  }
  // Circular layout
  var cx = 280, cy = 200, r = 140;
  var nodes = [];
  concepts.forEach(function(c, i) {
    var angle = (i / concepts.length) * Math.PI * 2 - Math.PI / 2;
    var x = cx + r * Math.cos(angle) - 50;
    var y = cy + r * Math.sin(angle) - 20;
    nodes.push({
      id: 'node_default_' + chKey + '_' + i,
      label: c.label,
      x: Math.round(x),
      y: Math.round(y),
      core: c.core
    });
  });
  var linkObjs = links.map(function(l, li) {
    return {
      id: 'link_default_' + chKey + '_' + li,
      from: nodes[l.from].id,
      to: nodes[l.to].id,
      label: l.label
    };
  });
  return { nodes: nodes, links: linkObjs };
}

