function loadStudent() {
  // V7: Try multi-student system first
  var sid = v7GetCurrentStudentId();
  if (sid) {
    var data = v7LoadStudentData(sid);
    if (data) return data;
  }
  // Fallback to old single-student format
  var saved = localStorage.getItem("ctp_student");
  if (saved) {
    var s = JSON.parse(saved);
    // Defensive checks
    if (!Array.isArray(s.questionHistory)) s.questionHistory = [];
    if (!s.dimensionScores) s.dimensionScores = {};
    if (!s.dimensionAttempts) s.dimensionAttempts = {};
    var _dims = ['clarity','precision','accuracy','relevance','consistency','logicalCorrectness','completeness','fairness'];
    _dims.forEach(function(d) {
      if (s.dimensionScores[d] === undefined) s.dimensionScores[d] = 0;
      if (s.dimensionAttempts[d] === undefined) s.dimensionAttempts[d] = 0;
    });
    if (!s.pblProjects) s.pblProjects = getDefaultPBLProjects();
    ['ch1','ch2'].forEach(function(ch) {
      if (!s.pblProjects[ch]) s.pblProjects[ch] = getDefaultPBLProjects()[ch];
      if (!s.pblProjects[ch].knowledgeMap || !s.pblProjects[ch].knowledgeMap || s.pblProjects[ch].knowledgeMap.nodes.length === 0) {
        s.pblProjects[ch].knowledgeMap = getDefaultKnowledgeMap(ch);
      }
    });
    // Ensure pblProjects exists (backward compatibility)
    if (!s.pblProjects) s.pblProjects = getDefaultPBLProjects();
    // Ensure all fields exist for each project
    ['ch1', 'ch2'].forEach(function(ch) {
      if (!s.pblProjects[ch]) {
        s.pblProjects[ch] = getDefaultPBLProjects()[ch];
      }
      // Backward compat: populate default knowledge map if empty
      var km = s.pblProjects[ch].knowledgeMap;
      if (!km || !km.nodes || km.nodes.length === 0) {
        s.pblProjects[ch].knowledgeMap = getDefaultKnowledgeMap(ch);
      }
    });
    return s;
  }
  return {
    id: "student_001",
    name: "Alex Student",
    pretestScore: null,
    pretestTaken: false,
    posttestScore: null,
    posttestTaken: false,
    chaptersCompleted: { ch1: false, ch2: false },
    chapterScores: { ch1: 0, ch2: 0 },
    dimensionScores: { clarity: 0, precision: 0, accuracy: 0, relevance: 0, consistency: 0, logicalCorrectness: 0, completeness: 0, fairness: 0 },
    dimensionAttempts: { clarity: 0, precision: 0, accuracy: 0, relevance: 0, consistency: 0, logicalCorrectness: 0, completeness: 0, fairness: 0 },
    questionHistory: [],
    practiceSessions: 0,
    streak: 0,
    lastActivity: null,
    recommendations: [],
    currentDifficulty: "basic",
    correctStreak: 0,
    pblProjects: {
      ch1: {
        status: 'in_progress',
        currentStep: 1,
        knowledgeMap: getDefaultKnowledgeMap('ch1'),
        reportDrafts: [],
        finalReport: '',
        finalKnowledgeMap: null,
        hintsUsed: {},
        iterations: 0,
        aiScore: null,
        aiFeedback: '',
        reflection: { q1: '', q2: '', q3: '' },
        submittedAt: null
      },
      ch2: {
        status: 'in_progress',
        currentStep: 1,
        knowledgeMap: getDefaultKnowledgeMap('ch2'),
        reportDrafts: [],
        finalReport: '',
        finalKnowledgeMap: null,
        hintsUsed: {},
        iterations: 0,
        aiScore: null,
        aiFeedback: '',
        reflection: { q1: '', q2: '', q3: '' },
        submittedAt: null
      }
    }
  };
}

function saveStudent() {
  // V7: Save to per-student key if logged in
  var sid = v7GetCurrentStudentId();
  if (sid) {
    v7SaveStudentData(sid, AppState.student);
  }
  // Also save to legacy key for backward compat
  localStorage.setItem("ctp_student", JSON.stringify(AppState.student));
}

function loadMessages() {
  // V7: Try per-student messages first
  var sid = v7GetCurrentStudentId();
  if (sid) {
    var msgKey = v7GetStudentDataKey(sid) + "_messages";
    var savedV7 = localStorage.getItem(msgKey);
    if (savedV7) {
      try { return JSON.parse(savedV7); } catch(e) {}
    }
  }
  var saved = localStorage.getItem("ctp_messages");
  if (saved) return JSON.parse(saved);
  return [
    {
      id: "msg_welcome",
      type: "info",
      title: "Welcome to Critical Thinking!",
      body: "Welcome to the Critical Thinking Learning Platform. Start by taking the pretest to assess your current level, then work through the chapters at your own pace. Your AI tutor is available 24/7 to guide your thinking!",
      time: Date.now(),
      read: false
    }
  ];
}

function saveMessages() {
  // V7: Save to per-student key
  var sid = v7GetCurrentStudentId();
  if (sid) {
    var msgKey = v7GetStudentDataKey(sid) + "_messages";
    localStorage.setItem(msgKey, JSON.stringify(AppState.messages));
  }
  localStorage.setItem("ctp_messages", JSON.stringify(AppState.messages));
}

function addMessage(msg) {
  AppState.messages.unshift({
    id: "msg_" + Date.now(),
    time: Date.now(),
    read: false,
    title: msg.title,
    body: msg.body,
    type: msg.type || "info"
  });
  saveMessages();
  updateMessageBadge();
}

function unreadCount() {
  return AppState.messages.filter(function(m) { return !m.read; }).length;
}

function updateMessageBadge() {
  var badge = document.getElementById("msgBadge");
  var count = unreadCount();
  if (count > 0) {
    badge.textContent = count > 9 ? "9+" : count;
    badge.style.display = "inline-block";
  } else {
    badge.style.display = "none";
  }
}

// =========================================
// NAVIGATION
// =========================================
document.querySelectorAll(".nav-item").forEach(function(item) {
  item.addEventListener("click", function() {
    var page = item.dataset.page;
    navigateTo(page);
  });
});

function navigateTo(page) {
  AppState.currentPage = page;
  document.querySelectorAll(".nav-item").forEach(function(i) { i.classList.remove("active"); });
  var navItem = document.querySelector('[data-page="' + page + '"]');
  if (navItem) navItem.classList.add("active");
  
  var titles = {
    dashboard: "Dashboard",
    messages: "Messages",
    pretest: "Pretest",
    chapter1: "Chapter 1: Introduction to Critical Thinking",
    chapter2: "Chapter 2: Recognizing Arguments",
    chapter3: "Chapter 3: Basic Logical Concepts",
    chapter4: "Chapter 4: Language",
    chapter5: "Chapter 5: Fallacies of Relevance",
    chapter6: "Chapter 6: Fallacies of Insufficient Evidence",
    chapter9: "Chapter 9: Categorical Logic",
    chapter10: "Chapter 10: Propositional Logic",
    radar: "Knowledge Network & Radar Chart",
    posttests: "Post-tests",
    practice: "Practice Quizzes",
    pbl: "Capstone PBL Project",
    pblDetail: "PBL Project Detail"
  };
  document.getElementById("topbarTitle").textContent = titles[page] || page;
  renderPage(page);
  updateTopProgress();
}

function renderPage(page) {
  var area = document.getElementById("contentArea");
  switch(page) {
    case "dashboard": renderDashboard(area); break;
    case "messages": renderMessages(area); break;
    case "pretest": startQuiz("pretest"); break;
    case "chapter1": renderChapter(area, 1); break;
    case "chapter2": renderChapter(area, 2); break;
    case "chapter3": renderChapter(area, 3); break;
    case "chapter4": renderChapter(area, 4); break;
    case "chapter5": renderChapter(area, 5); break;
    case "chapter6": renderChapter(area, 6); break;
    case "chapter7": renderChapter(area, 7); break;
    case "chapter8": renderChapter(area, 8); break;case "chapter9": renderChapter(area, 9); break;case "chapter10": renderChapter(area, 10); break;
    case "radar": renderRadar(area); break;
    case "posttests": renderPosttestPage(area); break;
    case "practice": renderPracticePage(area); break;
    case "pbl": renderPBLProjects(area); break;
    case "pblDetail": renderPBLDetail(area); break;
    default: area.innerHTML = "<p>Page not found</p>";
  }
}

function updateTopProgress() {
  var s = AppState.student;
  var total = 5;
  var completed = 0;
  if (s.pretestTaken) completed++;
  if (s.chaptersCompleted.ch1) completed++;
  if (s.chaptersCompleted.ch2) completed++;
  if (s.pblProjects && s.pblProjects.ch1 && s.pblProjects.ch1.status === 'completed') completed++;
  if (s.posttestTaken) completed++;
  var pct = Math.round(completed / total * 100);
  document.getElementById("topbarProgressText").textContent = pct + "% complete";
  document.getElementById("topbarProgressFill").style.width = pct + "%";
}

