function getDefaultRecommendations() {
  return [
    { title: "Start with the Pretest", text: "Take the pretest to establish your baseline. This helps the platform calibrate starting difficulty and gives you a clear picture of where to focus." },
    { title: "Read Chapter 1 First", text: "Chapter 1 introduces the foundational concepts and standards of critical thinking. Build this base before moving to argument analysis." },
    { title: "Use Your AI Tutor", text: "Click the chat icon in the bottom-right corner anytime you have a question. Your Socratic tutor will guide your thinking with thoughtful questions." }
  ];
}

function generateRecommendations() {
  var s = AppState.student;
  var recs = [];
  
  var dims = DIMENSIONS.map(function(d) { 
    return { dim: d, score: s.dimensionScores[d] || 0, attempts: s.dimensionAttempts[d] || 0 }; 
  });
  dims.sort(function(a, b) { return a.score - b.score; });
  
  var withAttempts = dims.filter(function(d) { return d.attempts > 0; });
  var weakest = withAttempts[0] || dims[0];
  var strongest = withAttempts.length > 0 ? withAttempts[withAttempts.length - 1] : dims[dims.length - 1];
  
  if (weakest && weakest.attempts > 0) {
    recs.push({
      title: "Focus on " + DIMENSION_NAMES[weakest.dim],
      text: "Your weakest area is currently " + DIMENSION_NAMES[weakest.dim] + " (" + weakest.score.toFixed(1) + "/10). Spend extra time reviewing the standards and practicing questions in this area."
    });
  }

  if (strongest && strongest.attempts > 0) {
    recs.push({
      title: "Leverage Your " + DIMENSION_NAMES[strongest.dim] + " Strength",
      text: "You're strong in " + DIMENSION_NAMES[strongest.dim] + " (" + strongest.score.toFixed(1) + "/10). Try advanced-level questions in this area to stretch your abilities even further."
    });
  }

  var totalQ = s.questionHistory.length;
  var correctQ = s.questionHistory.filter(function(q){return q.correct;}).length;
  var accuracy = totalQ > 0 ? correctQ / totalQ : 0;
  
  if (accuracy > 0.8 && s.currentDifficulty !== "advanced") {
    recs.push({
      title: "Try More Challenging Questions",
      text: "Your accuracy is strong! Consider pushing yourself with intermediate or advanced difficulty questions to deepen your understanding."
    });
  } else if (accuracy < 0.5 && s.currentDifficulty !== "basic" && totalQ > 3) {
    recs.push({
      title: "Build Foundations First",
      text: "Your accuracy suggests you might benefit from reviewing basic concepts. Try more basic-level questions to build confidence and understanding."
    });
  }

  recs.push({
    title: "Active Recall & Spaced Repetition",
    text: "For best retention, try active recall (testing yourself) rather than re-reading. Return to practice questions regularly (every 2-3 days) to strengthen memory pathways."
  });

  if (s.pretestTaken && s.posttestTaken) {
    var improvement = s.posttestScore - s.pretestScore;
    if (improvement > 0) {
      recs.push({
        title: "Great Progress! +" + Math.round(improvement) + "% Improvement",
        text: "You've improved significantly from pretest to post-test. Keep challenging yourself with advanced questions and consider teaching what you've learned to others."
      });
    }
  }

  return recs.slice(0, 5);
}

// =========================================
// MESSAGES
// =========================================
function renderMessages(area) {
  var msgs = AppState.messages;
  var html = '';
  html += '<h1 class="page-title">Messages</h1>';
  html += '<p class="page-subtitle">Your learning notifications and feedback</p>';
  html += '<div class="card"><div class="card-header"><div class="card-title">All Messages (' + msgs.length + ')</div>';
  html += '<button class="btn btn-outline btn-sm" onclick="markAllRead()">Mark all read</button></div>';
  html += '<div style="max-height:600px; overflow-y:auto;">';
  
  var iconMap = { info: "&#9432;", success: "&#10003;", warning: "&#9888;", error: "&#10007;" };
  
  msgs.forEach(function(msg) {
    var timeStr = new Date(msg.time).toLocaleString();
    html += '<div class="message-item ' + (msg.read ? '' : 'unread') + '" onclick="openMessage(\'' + msg.id + '\')">';
    html += '<div class="message-icon ' + (msg.type || 'info') + '">' + (iconMap[msg.type] || '&#9432;') + '</div>';
    html += '<div class="message-content"><div class="message-title">' + msg.title + '</div>';
    html += '<div class="message-preview">' + msg.body.substring(0, 80) + (msg.body.length > 80 ? '...' : '') + '</div></div>';
    html += '<div class="message-time">' + timeStr.split(',')[0] + '</div></div>';
  });

  html += '</div></div>';
  
  html += '<div class="msg-modal-overlay" id="messageModal">';
  html += '<div class="modal"><div class="modal-header"><div class="modal-title" id="messageModalTitle"></div>';
  html += '<button class="modal-close" onclick="closeMessageModal()">&times;</button></div>';
  html += '<div class="modal-body" id="messageModalBody"></div>';
  html += '<div class="modal-footer"><button class="btn btn-primary" onclick="closeMessageModal()">Close</button></div>';
  html += '</div></div>';

  area.innerHTML = html;
}

function openMessage(id) {
  var msg = AppState.messages.find(function(m) { return m.id === id; });
  if (!msg) return;
  msg.read = true;
  saveMessages();
  updateMessageBadge();
  
  document.getElementById("messageModalTitle").textContent = msg.title;
  document.getElementById("messageModalBody").innerHTML = 
    '<div class="text-sm text-muted mb-12">' + new Date(msg.time).toLocaleString() + '</div>' +
    '<div style="line-height:1.6; font-size:14px;">' + msg.body + '</div>';
  document.getElementById("messageModal").classList.add("show");
  
  // 只更新列表的未读状态，不要重建整个页面（否则modal会被清空）
  if (AppState.currentPage === "messages") {
    var msgItems = document.querySelectorAll(".message-item");
    msgItems.forEach(function(el, i) {
      var m = AppState.messages[i];
      if (m && m.read) {
        el.classList.remove("unread");
      }
    });
  }
}

function closeMessageModal() {
  document.getElementById("messageModal").classList.remove("show");
}

function markAllRead() {
  AppState.messages.forEach(function(m) { m.read = true; });
  saveMessages();
  updateMessageBadge();
  renderMessages(document.getElementById("contentArea"));
}

