function startChapterPosttest(chNum) {
  startQuiz('posttest-ch' + chNum);
}

function startQuiz(mode, chapterFilter) {
  var s = AppState.student;
  var questionPool;
  
  if (mode === "pretest") {
    // Randomly select 20 questions from the 40-question bank so each student gets a different set
    var shuffled = shuffle(PRETEST_QUESTIONS.slice());
    questionPool = shuffled.slice(0, 20).map(function(q){ return Object.assign({}, q, {chapter:"pretest"}); });
  } else if (mode === "posttest" || mode === "final-posttest") {
    var q1 = shuffle(CH1_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch1"}); });
    var q2 = shuffle(CH2_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch2"}); });
    var q3 = shuffle(CH3_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch3"}); });
    var q4 = shuffle(CH4_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch4"}); });
    var q5 = shuffle(CH5_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch5"}); });
    var q6 = shuffle(CH6_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch6"}); });
    var q7 = shuffle(CH7_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch7"}); });
    var q8 = shuffle(CH8_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch8"}); });
    var q9 = shuffle(CH9_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch9"}); });
    var q10 = shuffle(CH10_QUESTIONS.filter(function(q){return q.difficulty==="advanced";})).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter:"ch10"}); });
    questionPool = shuffle(q1.concat(q2).concat(q3).concat(q4).concat(q5).concat(q6).concat(q7).concat(q8).concat(q9).concat(q10));
  } else if (mode && mode.indexOf("posttest-ch") === 0) {
    var chNum = mode.replace("posttest-ch", "");
    var chKey = "ch" + chNum;
    var pool = chKey === "ch1" ? CH1_QUESTIONS : (chKey === "ch2" ? CH2_QUESTIONS : (chKey === "ch3" ? CH3_QUESTIONS : (chKey === "ch4" ? CH4_QUESTIONS : (chKey === "ch5" ? CH5_QUESTIONS : (chKey === "ch6" ? CH6_QUESTIONS : (chKey === "ch7" ? CH7_QUESTIONS : (chKey === "ch8" ? CH8_QUESTIONS : (chKey === "ch9" ? CH9_QUESTIONS : CH10_QUESTIONS))))))));
    var advancedPool = pool.filter(function(q){ return q.difficulty === "advanced"; });
    questionPool = shuffle(advancedPool).slice(0, 10).map(function(q){ return Object.assign({}, q, {chapter: chKey}); });
  } else if (mode && mode.indexOf("chapter") === 0) {
    var ch = mode === "chapter1" ? "ch1" : (mode === "chapter2" ? "ch2" : (mode === "chapter3" ? "ch3" : (mode === "chapter4" ? "ch4" : (mode === "chapter5" ? "ch5" : (mode === "chapter6" ? "ch6" : (mode === "chapter7" ? "ch7" : (mode === "chapter8" ? "ch8" : (mode === "chapter9" ? "ch9" : "ch10"))))))));
    var pool = ch === "ch1" ? CH1_QUESTIONS : (ch === "ch2" ? CH2_QUESTIONS : (ch === "ch3" ? CH3_QUESTIONS : (ch === "ch4" ? CH4_QUESTIONS : (ch === "ch5" ? CH5_QUESTIONS : (ch === "ch6" ? CH6_QUESTIONS : (ch === "ch7" ? CH7_QUESTIONS : (ch === "ch8" ? CH8_QUESTIONS : (ch === "ch9" ? CH9_QUESTIONS : CH10_QUESTIONS))))))));
    questionPool = selectAdaptiveQuestions(pool, s.currentDifficulty, 10).map(function(q){ return Object.assign({}, q, {chapter: ch}); });
  } else if (mode === "practice") {
    var pool;
    if (chapterFilter) {
      pool = chapterFilter === "ch1" ? CH1_QUESTIONS : (chapterFilter === "ch2" ? CH2_QUESTIONS : (chapterFilter === "ch3" ? (ch === "ch3" ? CH3_QUESTIONS : (ch === "ch4" ? CH4_QUESTIONS : CH5_QUESTIONS)) : (chapterFilter === "ch4" ? CH4_QUESTIONS : (chapterFilter === "ch5" ? CH5_QUESTIONS : (chapterFilter === "ch6" ? CH6_QUESTIONS : (chapterFilter === "ch7" ? CH7_QUESTIONS : (chapterFilter === "ch8" ? CH8_QUESTIONS : (chapterFilter === "ch9" ? CH9_QUESTIONS : CH10_QUESTIONS))))))));
    } else {
      pool = CH1_QUESTIONS.concat(CH2_QUESTIONS).concat(CH3_QUESTIONS).concat(CH4_QUESTIONS).concat(CH5_QUESTIONS).concat(CH6_QUESTIONS).concat(CH7_QUESTIONS).concat((chapterFilter === "ch8" ? CH8_QUESTIONS : (chapterFilter === "ch9" ? CH9_QUESTIONS : CH10_QUESTIONS))).map(function(q){ 
        return Object.assign({}, q, {chapter: q.id.indexOf('ch1')===0 ? 'ch1' : (q.id.indexOf('ch2')===0 ? 'ch2' : (q.id.indexOf('ch3')===0 ? 'ch3' : (q.id.indexOf('ch4')===0 ? 'ch4' : (q.id.indexOf('ch5')===0 ? 'ch5' : (q.id.indexOf('ch6')===0 ? 'ch6' : (q.id.indexOf('ch7')===0 ? 'ch7' : (q.id.indexOf('ch8')===0 ? 'ch8' : (q.id.indexOf('ch9')===0 ? 'ch9' : 'ch10'))))))))});
      });
    }
    questionPool = selectAdaptiveQuestions(pool, s.currentDifficulty, 10);
  } else {
    questionPool = CH1_QUESTIONS.concat(CH2_QUESTIONS).concat(CH3_QUESTIONS).concat(CH4_QUESTIONS).map(function(q){ 
      return Object.assign({}, q, {chapter: q.id.indexOf('ch1')===0 ? 'ch1' : (q.id.indexOf('ch2')===0 ? 'ch2' : (q.id.indexOf('ch3')===0 ? 'ch3' : 'ch4'))}); 
    });
  }

  // Shuffle options for each question to prevent pattern guessing (e.g. always B)
  questionPool = questionPool.map(function(q) {
    var correctText = q.options[q.correctAnswer];
    var shuffledOptions = shuffle(q.options.slice());
    var newCorrectIndex = shuffledOptions.indexOf(correctText);
    return Object.assign({}, q, {
      options: shuffledOptions,
      correctAnswer: newCorrectIndex
    });
  });

  AppState.quizState = {
    mode: mode,
    questions: questionPool,
    currentIndex: 0,
    answers: [],
    submitted: [],
    score: 0,
    startTime: Date.now()
  };

  renderQuiz();
}

function selectAdaptiveQuestions(pool, difficulty, count) {
  var shuffled = shuffle(pool.slice());
  var atLevel = shuffled.filter(function(q){ return q.difficulty === difficulty; });
  var result = [];
  
  var atLevelCount = Math.ceil(count * 0.7);
  result = result.concat(atLevel.slice(0, atLevelCount));
  
  var remaining = shuffled.filter(function(q){ return result.indexOf(q) === -1; });
  result = result.concat(remaining.slice(0, count - result.length));
  
  return shuffle(result).slice(0, count);
}

function shuffle(arr) {
  var a = arr.slice();
  for (var i = a.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}

function renderQuiz() {
  var qs = AppState.quizState;
  var q = qs.questions[qs.currentIndex];
  var progress = (qs.currentIndex / qs.questions.length) * 100;
  var answered = qs.answers[qs.currentIndex] !== undefined;
  var isSubmitted = qs.submitted[qs.currentIndex] === true;

  var titleText = qs.mode === 'pretest' ? 'Pretest' : 
    (qs.mode === 'posttest' || qs.mode === 'final-posttest') ? 'Post-test' : 
    (qs.mode && qs.mode.indexOf('posttest-ch')===0) ? 'Chapter Post-test' : 
    (qs.mode && qs.mode.indexOf('chapter')===0) ? 'Chapter Quiz' : 'Practice Quiz';

  var html = '';
  html += '<div class="quiz-container"><div class="card">';
  html += '<div class="card-header"><div class="card-title">' + titleText + '</div>';
  html += '<span class="difficulty-badge ' + q.difficulty + '">' + q.difficulty + '</span></div>';
  html += '<div class="card-body">';
  html += '<div class="quiz-progress-bar"><div class="quiz-progress-fill" style="width:' + progress + '%"></div></div>';
  html += '<div class="quiz-meta"><span>Question ' + (qs.currentIndex + 1) + ' of ' + qs.questions.length + '</span><span>' + q.knowledgePoint + '</span></div>';
  html += '<div class="question-text">' + q.question + '</div>';
  html += '<div id="optionsContainer">';

  q.options.forEach(function(opt, i) {
    var classes = "option-item";
    if (isSubmitted) {
      if (i === q.correctAnswer) classes += " correct";
      if (i === qs.answers[qs.currentIndex] && i !== q.correctAnswer) classes += " incorrect";
    } else if (qs.answers[qs.currentIndex] === i) {
      classes += " selected";
    }
    var letter = String.fromCharCode(65 + i);
    var clickHandler = isSubmitted ? '' : 'onclick="selectOption(' + i + ')"';
    html += '<div class="' + classes + '" ' + clickHandler + '>';
    html += '<div class="option-label">' + letter + '</div>';
    html += '<div class="option-text">' + opt + '</div>';
    html += '</div>';
  });

  if (isSubmitted) {
    var isCorrect = qs.answers[qs.currentIndex] === q.correctAnswer;
    html += '<div class="explanation-box">';
    html += '<strong>' + (isCorrect ? '&#10003; Correct!' : '&#10007; Incorrect') + '</strong><br>';
    html += q.explanation;
    html += '</div>';
  }

  html += '</div><div class="quiz-actions">';
  html += '<button class="btn btn-outline" onclick="exitQuiz()">Exit</button>';
  html += '<div>';
  
  if (isSubmitted) {
    if (qs.currentIndex < qs.questions.length - 1) {
      html += '<button class="btn btn-primary" onclick="nextQuestion()">Next Question &rarr;</button>';
    } else {
      html += '<button class="btn btn-success" onclick="finishQuiz()">Finish Quiz</button>';
    }
  } else {
    html += '<button class="btn btn-primary" onclick="submitAnswer()" id="submitBtn" ' + (answered ? '' : 'disabled') + '>Submit Answer</button>';
  }

  html += '</div></div></div></div></div>';

  document.getElementById("contentArea").innerHTML = html;
}

function selectOption(index) {
  if (AppState.quizState.submitted[AppState.quizState.currentIndex] === true) return;
  AppState.quizState.answers[AppState.quizState.currentIndex] = index;
  var btn = document.getElementById("submitBtn");
  if (btn) btn.disabled = false;
  renderQuiz();
}

function submitAnswer() {
  var qs = AppState.quizState;
  var idx = qs.currentIndex;
  var q = qs.questions[idx];
  var selected = qs.answers[idx];
  
  if (selected === undefined || selected === null) return;
  if (qs.submitted[idx] === true) return; // 防止重复提交
  qs.submitted[idx] = true; // 标记为已提交
  
  var correct = selected === q.correctAnswer;
  
  var s = AppState.student;
  s.questionHistory.push({
    questionId: q.id,
    correct: correct,
    difficulty: q.difficulty,
    dimension: q.dimension,
    chapter: q.chapter || 'ch1',
    timestamp: Date.now()
  });
  
  // Update dimension scores: ability = sum(difficulty_weight * result) / sum(difficulty_weight) * 10
  var dim = q.dimension;
  s.dimensionAttempts[dim] = (s.dimensionAttempts[dim] || 0) + 1;
  
  var correctWeight = 0;
  var allWeight = 0;
  s.questionHistory.forEach(function(h) {
    if (h.dimension === dim) {
      var w = DIFFICULTY_WEIGHTS[h.difficulty];
      allWeight += w;
      if (h.correct) correctWeight += w;
    }
  });
  s.dimensionScores[dim] = allWeight > 0 ? (correctWeight / allWeight) * 10 : 0;
  
  // Adaptive difficulty
  if (correct) {
    s.correctStreak++;
    if (s.correctStreak >= 2) {
      var currentIdx = DIFFICULTY_ORDER.indexOf(s.currentDifficulty);
      if (currentIdx < DIFFICULTY_ORDER.length - 1) {
        s.currentDifficulty = DIFFICULTY_ORDER[currentIdx + 1];
      }
      s.correctStreak = 0;
    }
  } else {
    s.correctStreak = 0;
    var currentIdx = DIFFICULTY_ORDER.indexOf(s.currentDifficulty);
    if (currentIdx > 0) {
      s.currentDifficulty = DIFFICULTY_ORDER[currentIdx - 1];
    }
  }
  
  if (correct) qs.score++;
  
  s.lastActivity = Date.now();
  // Full recalculation to ensure all dimension scores are accurate
  recalculateDimensionScores();
  saveStudent();
  renderQuiz();
  // Auto sync to Feishu after each answer
  autoSyncToFeishu();
}

function nextQuestion() {
  AppState.quizState.currentIndex++;
  renderQuiz();
}

function exitQuiz() {
  if (confirm("Exit the quiz? Your progress will not be saved for this quiz session.")) {
    AppState.quizState = null;
    navigateTo("dashboard");
  }
}

function finishQuiz() {
  var qs = AppState.quizState;
  var s = AppState.student;
  // Bug fix: recalculate correct count from answers array instead of relying on qs.score
  var correctCount = 0;
  qs.questions.forEach(function(q, i) {
    if (qs.answers[i] === q.correctAnswer) correctCount++;
  });
  qs.score = correctCount;
  var pct = Math.round((correctCount / qs.questions.length) * 100);
  
  if (qs.mode === "pretest") {
    s.pretestScore = pct;
    s.pretestTaken = true;
    if (pct >= 70) s.currentDifficulty = "intermediate";
    if (pct >= 85) s.currentDifficulty = "advanced";
    
    addMessage({
      type: "success",
      title: "Pretest Complete!",
      body: "You scored " + pct + "% on the pretest. Based on your results, your starting difficulty level is " + s.currentDifficulty + ". View your Knowledge Network to see your strengths and areas for growth."
    });
    s.recommendations = generateRecommendations();

    // All PBL projects are always available
  }
  
  if (qs.mode === "posttest" || qs.mode === "final-posttest") {
    s.posttestScore = pct;
    s.posttestTaken = true;
    s.finalPosttestScore = pct;
    s.finalPosttestDone = true;
    var improvement = pct - (s.pretestScore || 0);
    addMessage({
      type: "success",
      title: "Post-test Complete!",
      body: "You scored " + pct + "% on the post-test! " + (improvement > 0 ? 'That is a ' + improvement + '% improvement from your pretest score — great work!' : 'Review your results and try practice quizzes to strengthen weaker areas.')
    });
    s.recommendations = generateRecommendations();
  }
  
  // Chapter posttests
  if (qs.mode && qs.mode.indexOf("posttest-ch") === 0) {
    var chNum = qs.mode.replace("posttest-ch", "");
    var chKey = "ch" + chNum;
    s[chKey + '_posttestScore'] = pct;
    s[chKey + '_posttestDone'] = true;
    addMessage({
      type: "success",
      title: "Chapter " + chNum + " Post-test Complete!",
      body: "You scored " + pct + "% on the Chapter " + chNum + " post-test (10 advanced questions)."
    });
    s.recommendations = generateRecommendations();
  }
  
  if (qs.mode && qs.mode.indexOf("chapter") === 0) {
    var chNum = qs.mode === "chapter1" ? "1" : (qs.mode === "chapter2" ? "2" : (qs.mode === "chapter3" ? "3" : (qs.mode === "chapter4" ? "4" : (qs.mode === "chapter5" ? "5" : (qs.mode === "chapter6" ? "6" : (qs.mode === "chapter7" ? "7" : "8"))))));
    var chKey = "ch" + chNum;
    s.chapterScores[chKey] = Math.max(s.chapterScores[chKey] || 0, pct);
    if (pct >= 70) {
      s.chaptersCompleted[chKey] = true;

      // All PBL projects are always available
      var nextCh = chNum === "1" ? "Move on to Chapter 2 to learn about recognizing arguments!" : (chNum === "2" ? "Move on to Chapter 3 to master basic logical concepts!" : (chNum === "3" ? "Move on to Chapter 4 to explore language and meaning!" : (chNum === "4" ? "Move on to Chapter 5 to learn about inductive reasoning!" : (chNum === "5" ? "Move on to Chapter 6 to explore deductive reasoning!" : (chNum === "6" ? "Move on to Chapter 7 to analyze arguments!" : (chNum === "7" ? "Move on to Chapter 8 to evaluate arguments and truth claims!" : "You have completed all eight chapters — try the post-test to measure your overall progress!"))))));
      addMessage({
        type: "success",
        title: "Chapter " + chNum + " Completed!",
        body: "Congratulations! You scored " + pct + "% on the Chapter " + chNum + " quiz and have mastered this chapter. " + nextCh
      });
    }
    s.recommendations = generateRecommendations();
  }
  
  if (qs.mode === "practice") {
    s.practiceSessions++;
    s.recommendations = generateRecommendations();
  }
  
  // Ensure dimension scores are fully recalculated from history
  recalculateDimensionScores();
  saveStudent();
  renderQuizResult();
}

function renderQuizResult() {
  var qs = AppState.quizState;
  // Bug fix: recalculate correct count from answers array for accurate display
  var correctCount = 0;
  qs.questions.forEach(function(q, i) {
    if (qs.answers[i] === q.correctAnswer) correctCount++;
  });
  var pct = Math.round((correctCount / qs.questions.length) * 100);
  
  var dimensionStats = {};
  DIMENSIONS.forEach(function(d) { dimensionStats[d] = { correct: 0, total: 0 }; });
  
  qs.questions.forEach(function(q, i) {
    var dim = q.dimension;
    dimensionStats[dim].total++;
    if (qs.answers[i] === q.correctAnswer) dimensionStats[dim].correct++;
  });

  var titleText = qs.mode === 'pretest' ? 'Pretest Results' : 
    (qs.mode === 'posttest' || qs.mode === 'final-posttest') ? 'Post-test Results' : 
    (qs.mode && qs.mode.indexOf('posttest-ch')===0) ? 'Chapter Post-test Results' : 
    (qs.mode && qs.mode.indexOf('chapter')===0) ? 'Chapter Quiz Results' : 'Practice Results';

  var html = '';
  html += '<div class="quiz-container"><div class="card">';
  html += '<div class="card-header"><div class="card-title">' + titleText + '</div></div>';
  html += '<div class="card-body">';
  html += '<div class="result-header"><div class="result-score">' + pct + '%</div>';
  html += '<div class="result-label">' + correctCount + ' out of ' + qs.questions.length + ' correct</div></div>';
  
  html += '<div class="result-detail">';
  html += '<div class="result-detail-item"><span class="result-detail-label">Difficulty Level</span><span class="result-detail-value" style="text-transform:capitalize;">' + AppState.student.currentDifficulty + '</span></div>';
  html += '<div class="result-detail-item"><span class="result-detail-label">Total Questions</span><span class="result-detail-value">' + qs.questions.length + '</span></div>';

  DIMENSIONS.forEach(function(dim) {
    if (dimensionStats[dim].total > 0) {
      var dimPct = Math.round(dimensionStats[dim].correct / dimensionStats[dim].total * 100);
      var colorClass = dimPct >= 70 ? 'text-success' : dimPct >= 50 ? 'text-warning' : 'text-danger';
      html += '<div class="result-detail-item"><span class="result-detail-label">' + DIMENSION_NAMES[dim] + '</span><span class="result-detail-value ' + colorClass + '">' + dimPct + '%</span></div>';
    }
  });

  html += '</div>';
  html += '<div style="display:flex; gap:10px; margin-top:24px;">';
  html += '<button class="btn btn-outline flex-1" onclick="navigateTo(\'dashboard\')">Back to Dashboard</button>';
  html += '<button class="btn btn-accent flex-1" onclick="startQuiz(\'' + (qs.mode && qs.mode.indexOf('chapter')===0 ? 'practice' : qs.mode) + '\')">Try Again</button>';
  html += '</div></div></div></div>';

  document.getElementById("contentArea").innerHTML = html;
}

// =========================================
// RADAR CHART (SVG)
// =========================================

// Recalculate all dimension scores from full question history
// Aggregates ALL records: pretest, chapter quizzes, post-test, practice
// Difficulty weights: basic=1, intermediate=2, advanced=3
// Dimension score = sum(difficulty_weight × result) / sum(difficulty_weight) × 10
function recalculateDimensionScores() {
  var s = AppState.student;
  if (!s.questionHistory || s.questionHistory.length === 0) {
    DIMENSIONS.forEach(function(d) {
      s.dimensionScores[d] = 0;
      s.dimensionAttempts[d] = 0;
    });
    return;
  }
  
  var correctW = {};
  var totalW = {};
  var attempts = {};
  DIMENSIONS.forEach(function(d) { correctW[d] = 0; totalW[d] = 0; attempts[d] = 0; });
  
  s.questionHistory.forEach(function(h) {
    var dim = h.dimension;
    if (!dim || DIMENSIONS.indexOf(dim) === -1) return;
    var w = DIFFICULTY_WEIGHTS[h.difficulty] || 1;
    totalW[dim] += w;
    attempts[dim]++;
    if (h.correct) correctW[dim] += w;
  });
  
  DIMENSIONS.forEach(function(d) {
    s.dimensionScores[d] = totalW[d] > 0 ? (correctW[d] / totalW[d]) * 10 : 0;
    s.dimensionAttempts[d] = attempts[d];
  });
}


function renderRadar(area) {
  recalculateDimensionScores();
  var s = AppState.student;
  var scores = DIMENSIONS.map(function(d) { return s.dimensionScores[d] || 0; });
  var attempts = DIMENSIONS.map(function(d) { return s.dimensionAttempts[d] || 0; });
  var totalAttempts = attempts.reduce(function(a,b) { return a+b; }, 0);
  var avgScore = totalAttempts > 0 ? (scores.reduce(function(a,b){return a+b;}, 0) / 8).toFixed(1) : "0.0";

  var radarSvg = generateRadarSVG(scores, DIMENSIONS.map(function(d) { return DIMENSION_NAMES[d]; }));

  var html = "";
  html += "<h1 class=\"page-title\">Knowledge Network & Radar Analysis</h1>";
  html += "<p class=\"page-subtitle\">Your critical thinking skills across 8 dimensions</p>";
  
  // Top summary stats
  html += "<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px;\">";
  html += "<div class=\"card\" style=\"text-align:center;padding:20px 16px;\"><div style=\"font-size:28px;font-weight:700;color:var(--accent);\">" + totalAttempts + "</div><div class=\"text-sm text-muted\">Questions Answered</div></div>";
  html += "<div class=\"card\" style=\"text-align:center;padding:20px 16px;\"><div style=\"font-size:28px;font-weight:700;color:var(--success);\">" + avgScore + "</div><div class=\"text-sm text-muted\">Avg Score / 10</div></div>";
  var correctCount = s.questionHistory.filter(function(h){ return h.correct; }).length;
  var accRate = totalAttempts > 0 ? Math.round(correctCount / totalAttempts * 100) : 0;
  html += "<div class=\"card\" style=\"text-align:center;padding:20px 16px;\"><div style=\"font-size:28px;font-weight:700;color:#f39c12;\">" + accRate + "%</div><div class=\"text-sm text-muted\">Accuracy Rate</div></div>";
  var activeDims = attempts.filter(function(a){ return a > 0; }).length;
  html += "<div class=\"card\" style=\"text-align:center;padding:20px 16px;\"><div style=\"font-size:28px;font-weight:700;color:#9b59b6;\">" + activeDims + "/8</div><div class=\"text-sm text-muted\">Dimensions Trained</div></div>";
  html += "</div>";

  html += "<div class=\"grid-2\">";
  
  // Left: Radar chart
  html += "<div class=\"card\"><div class=\"card-header\"><div class=\"card-title\">Skill Radar Chart</div>";
  html += "<span class=\"text-sm text-muted\">" + totalAttempts + " questions answered</span></div>";
  html += "<div class=\"card-body\"><div class=\"radar-container\">" + radarSvg + "</div></div></div>";

  // Right: Dimension bars (clearer visual)
  html += "<div>";
  html += "<div class=\"card\"><div class=\"card-header\"><div class=\"card-title\">Dimension Breakdown</div></div><div class=\"card-body\">";

  var rankedDims = DIMENSIONS.map(function(d, i) {
    return { dim: d, name: DIMENSION_NAMES[d], score: scores[i], attempts: attempts[i] };
  }).sort(function(a, b) { return b.score - a.score; });

  var colors = ["#2ecc71", "#27ae60", "#3498db", "#2980b9", "#9b59b6", "#8e44ad", "#f39c12", "#e74c3c"];
  rankedDims.forEach(function(item, idx) {
    var pct = Math.round(item.score / 10 * 100);
    var color = colors[idx];
    var ih = '<div style="margin-bottom:18px;">';
    ih += '<div class="flex-between mb-6">';
    ih += '<span style="font-size:14px;font-weight:600;color:var(--text-primary);">' + (idx+1) + '. ' + item.name + '</span>';
    ih += '<span style="font-size:14px;font-weight:700;color:' + color + ';">' + item.score.toFixed(1) + '/10</span>';
    ih += '</div>';
    ih += '<div style="height:12px;background:#eef1f5;border-radius:6px;overflow:hidden;">';
    ih += '<div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,' + color + ',' + color + 'dd);border-radius:6px;transition:width 0.6s ease;"></div>';
    ih += '</div>';
    ih += '<div style="font-size:12px;color:var(--text-secondary);margin-top:4px;">' + item.attempts + ' question' + (item.attempts === 1 ? '' : 's') + ' attempted</div>';
    ih += '</div>';
    html += ih;
  });

  html += "</div></div>";

  // Learning summary card
  html += "<div class=\"card mt-16\"><div class=\"card-header\"><div class=\"card-title\">Learning Summary</div></div><div class=\"card-body\">";
  html += "<div class=\"text-sm text-secondary mb-8\"><strong>Strongest area:</strong> " + rankedDims[0].name + " (" + rankedDims[0].score.toFixed(1) + "/10)</div>";
  html += "<div class=\"text-sm text-secondary mb-8\"><strong>Needs improvement:</strong> " + rankedDims[rankedDims.length-1].name + " (" + rankedDims[rankedDims.length-1].score.toFixed(1) + "/10)</div>";
  html += "<div class=\"text-sm text-secondary\"><strong>Overall score:</strong> " + avgScore + "/10 across " + totalAttempts + " questions</div>";
  html += "</div></div>";
  html += "</div></div>";

  area.innerHTML = html;
}

function generateRadarSVG(scores, labels) {
  var size = 360;
  var cx = size / 2;
  var cy = size / 2;
  var maxVal = 10;
  var radius = 130;
  var n = scores.length;
  var angleStep = (2 * Math.PI) / n;
  var startAngle = -Math.PI / 2;

  var gridPolygons = "";
  [2, 4, 6, 8, 10].forEach(function(level) {
    var r = (level / maxVal) * radius;
    var points = "";
    for (var i = 0; i < n; i++) {
      var angle = startAngle + i * angleStep;
      var x = cx + r * Math.cos(angle);
      var y = cy + r * Math.sin(angle);
      points += x.toFixed(1) + "," + y.toFixed(1) + " ";
    }
    gridPolygons += '<polygon points="' + points + '" fill="none" stroke="#e0e6ed" stroke-width="1"/>';
  });

  var axisLines = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var x = cx + radius * Math.cos(angle);
    var y = cy + radius * Math.sin(angle);
    axisLines += '<line x1="' + cx.toFixed(1) + '" y1="' + cy.toFixed(1) + '" x2="' + x.toFixed(1) + '" y2="' + y.toFixed(1) + '" stroke="#e0e6ed" stroke-width="1"/>';
  }

  var dataPoints = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var r = (scores[i] / maxVal) * radius;
    var x = cx + r * Math.cos(angle);
    var y = cy + r * Math.sin(angle);
    dataPoints += x.toFixed(1) + "," + y.toFixed(1) + " ";
  }

  var dataDots = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var r = (scores[i] / maxVal) * radius;
    var x = cx + r * Math.cos(angle);
    var y = cy + r * Math.sin(angle);
    dataDots += '<circle cx="' + x.toFixed(1) + '" cy="' + y.toFixed(1) + '" r="4" fill="#3498db" stroke="#fff" stroke-width="2"/>';
  }

  var labelTexts = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var labelR = radius + 22;
    var x = cx + labelR * Math.cos(angle);
    var y = cy + labelR * Math.sin(angle);
    var anchor = "middle";
    if (Math.cos(angle) > 0.3) anchor = "start";
    if (Math.cos(angle) < -0.3) anchor = "end";
    labelTexts += '<text x="' + x.toFixed(1) + '" y="' + y.toFixed(1) + '" text-anchor="' + anchor + '" dominant-baseline="middle" font-size="11" fill="#5a6c7d" font-weight="500">' + labels[i] + '</text>';
  }

  return '<svg viewBox="0 0 ' + size + ' ' + size + '" width="100%" style="max-width:400px; display:block; margin:0 auto;">' +
    gridPolygons + axisLines +
    '<polygon points="' + dataPoints + '" fill="rgba(52, 152, 219, 0.25)" stroke="#3498db" stroke-width="2"/>' +
    dataDots + labelTexts + '</svg>';
}


