var PBL_SELECTED_CAPSTONE = null;

function getCapstoneState() {
  var s = AppState.student;
  if (!s.capstoneProjectId || !s.capstoneSelected) {
    return {
      capstoneProjectId: null,
      capstoneSelected: false,
      milestones: {
        ch1: { status: 'available', completedAt: null },
        ch2: { status: 'available', completedAt: null },
        ch3: { status: 'available', completedAt: null },
        ch4: { status: 'available', completedAt: null },
        ch5: { status: 'available', completedAt: null },
        ch6: { status: 'available', completedAt: null }
      }
    };
  }
  return {
    capstoneProjectId: s.capstoneProjectId,
    capstoneSelected: s.capstoneSelected,
    milestones: s.milestones || {
      ch1: { status: 'available', completedAt: null },
      ch2: { status: 'available', completedAt: null },
      ch3: { status: 'available', completedAt: null },
      ch4: { status: 'available', completedAt: null },
      ch5: { status: 'available', completedAt: null },
      ch6: { status: 'available', completedAt: null }
    }
  };
}

function getCapstoneProject(projectId) {
  return PBL_CAPSTONE_PROJECTS[projectId] || null;
}

function getCurrentCapstoneProject() {
  var s = AppState.student;
  if (!s.capstoneProjectId) return null;
  return getCapstoneProject(s.capstoneProjectId);
}

function selectCapstoneProject(projectId) {
  var s = AppState.student;
  s.capstoneProjectId = projectId;
  s.capstoneSelected = true;
  // Initialize milestone tracking
  if (!s.milestones) {
    s.milestones = {
      ch1: { status: 'available', completedAt: null, deliverable: '' },
      ch2: { status: 'available', completedAt: null, deliverable: '' },
      ch3: { status: 'available', completedAt: null, deliverable: '' },
      ch4: { status: 'available', completedAt: null, deliverable: '' },
      ch5: { status: 'available', completedAt: null, deliverable: '' },
      ch6: { status: 'available', completedAt: null, deliverable: '' },
      ch7: { status: 'available', completedAt: null, deliverable: '' }
    };
  }
  // Unlock ch1 milestone if pretest taken
  if (s.pretestTaken && s.milestones.ch1.status === 'locked') {
    s.milestones.ch1.status = 'available';
  }
  saveStudent();
  navigateTo('pbl');
}

function updateMilestoneUnlockStatus() {
  // All milestones are always available (full unlock)
  var s = AppState.student;
  if (!s.milestones) return;
  var ms = s.milestones;
  ['ch1', 'ch2', 'ch3', 'ch4', 'ch5', 'ch6', 'ch7', 'ch8'].forEach(function(ch) {
    if (ms[ch] && ms[ch].status === 'locked') ms[ch].status = 'available';
  });
  saveStudent();
}

function getMilestoneProgress() {
  var s = AppState.student;
  if (!s.milestones) return { completed: 0, total: 10, pct: 0 };
  var completed = 0;
  ['ch1', 'ch2', 'ch3', 'ch4', 'ch5', 'ch6', 'ch7', 'ch8'].forEach(function(ch) {
    if (s.milestones[ch] && s.milestones[ch].status === 'completed') completed++;
  });
  return { completed: completed, total: 10, pct: Math.round(completed / 8 * 100) };
}
;

