var PBL_CURRENT_PROJECT = null;

function getPBLProject(chKey) {
  var s = AppState.student;
  if (!s.pblProjects) {
    s.pblProjects = getDefaultPBLProjects();
    saveStudent();
  }
  if (!s.pblProjects[chKey]) {
    s.pblProjects[chKey] = getDefaultPBLProjects()[chKey];
    saveStudent();
  }
  return s.pblProjects[chKey];
}

// Get PBL display data - uses capstone milestone if available
function getPBLDisplayData(chKey) {
  var s = AppState.student;
  if (s.capstoneProjectId && s.capstoneSelected) {
    var capstone = getCapstoneProject(s.capstoneProjectId);
    if (capstone && capstone.milestones && capstone.milestones[chKey]) {
      var ms = capstone.milestones[chKey];
      // Return in PBL_PROJECT_DATA compatible format
      return {
        id: chKey,
        chapter: parseInt(chKey.replace('ch', '')),
        title: ms.title,
        subtitle: capstone.title + ' — Chapter Milestone',
        icon: capstone.icon,
        scenario: {
          title: capstone.title,
          icon: capstone.icon,
          text: capstone.scenarioDescription
        },
        task: {
          title: ms.title,
          role: 'Critical Thinking Analyst — ' + capstone.title,
          description: ms.taskDescription,
          deliverable: ms.deliverablePrompt,
          deliverables: [
            { icon: '📝', name: 'Structured Analysis Report', desc: ms.deliverablePrompt || 'A clear, well-reasoned analysis applying chapter concepts' },
            { icon: '🧠', name: 'Concept Quiz', desc: 'Test your understanding of key concepts from this chapter' },
            { icon: '📊', name: 'AI Evaluation & Feedback', desc: 'Get personalized AI feedback on your critical thinking skills' }
          ],
          rubric: [
            { dimension: 'Clarity', desc: 'Is your analysis clear, precise, and easy to follow?', weight: 20 },
            { dimension: 'Accuracy', desc: 'Are your claims accurate and supported by evidence from the scenario?', weight: 20 },
            { dimension: 'Logic', desc: 'Is your reasoning logically sound and well-structured?', weight: 25 },
            { dimension: 'Relevance', desc: 'Do you stay focused on the core problem and key issues?', weight: 15 },
            { dimension: 'Depth', desc: 'Do you go beneath the surface to explore underlying causes?', weight: 20 }
          ],
          guidingQuestions: (ms.guidingQuestions || []).map(function(q, idx) {
            return {
              id: 'gq_' + idx,
              question: q,
              hints: [
                'Try to identify the key concepts from this chapter that are most relevant here.',
                'Think about what evidence or examples from the scenario would support your answer.',
                'Consider alternative perspectives — what would someone who disagrees say?'
              ]
            };
          }),
          suggestedConcepts: ms.suggestedConcepts || [],
          outputFormat: ms.outputFormat || 'structured analysis'
        },
        guidingQuestions: (ms.guidingQuestions || []).map(function(q, idx) {
          return {
            id: 'gq_' + idx,
            question: q,
            hints: [
              'Try to identify the key concepts from this chapter that are most relevant here.',
              'Think about what evidence or examples from the scenario would support your answer.',
              'Consider alternative perspectives — what would someone who disagrees say?'
            ]
          };
        }),
        suggestedConcepts: ms.suggestedConcepts || [],
        guidance: {
          tip: 'Apply the critical thinking concepts from this chapter to analyze the project scenario.',
          framework: 'Use the chapter\'s key concepts as your analytical lens. Focus on applying intellectual standards to produce a clear, well-reasoned deliverable.'
        },
        reflection: {
          q1: 'What was the most important insight you gained from applying this chapter\'s concepts?',
          q2: 'How has this milestone changed your perspective on the overall project?',
          q3: 'What would you do differently if you were to approach this task again?'
        }
      };
    }
  }
  // Fallback to original data
  return PBL_PROJECT_DATA[chKey];
}



