var DECK_CURRENT_SLIDE = 0;
function initDeckSlider() {
  DECK_CURRENT_SLIDE = 0;
  updateDeckView();
}
function updateDeckView() {
  var slides = document.querySelectorAll('.deck-slide');
  slides.forEach(function(s, i) {
    s.style.display = i === DECK_CURRENT_SLIDE ? 'block' : 'none';
  });
  var counter = document.getElementById('deckCounter');
  if (counter) counter.textContent = (DECK_CURRENT_SLIDE + 1) + ' / ' + slides.length;
}
function nextDeckSlide() {
  var slides = document.querySelectorAll('.deck-slide');
  if (DECK_CURRENT_SLIDE < slides.length - 1) {
    DECK_CURRENT_SLIDE++;
    updateDeckView();
  }
}
function prevDeckSlide() {
  if (DECK_CURRENT_SLIDE > 0) {
    DECK_CURRENT_SLIDE--;
    updateDeckView();
  }
}

function renderPBLDetail(area) {
  var chKey = PBL_CURRENT_PROJECT;
  if (!chKey) { navigateTo('pbl'); return; }
  
  var proj = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  
  var steps = [
    { num: 1, label: 'Scenario' },
    { num: 2, label: 'Task' },
    { num: 3, label: 'Guidance' },
    { num: 4, label: 'Build' },
    { num: 5, label: 'Submit' },
    { num: 6, label: 'Evaluate' }
  ];
  
  var html = '';
  html += '<button class="btn btn-outline btn-sm mb-16" onclick="navigateTo(\'pbl\')">\u2190 Back to Projects</button>';
  html += '<h1 class="page-title">' + data.title + '</h1>';
  html += '<p class="page-subtitle">' + data.subtitle + '</p>';
  
  // Step navigation + forum tab
  html += '<div class="pbl-steps-nav">';
  steps.forEach(function(step) {
    var cls = '';
    if (step.num < proj.currentStep) cls = 'completed';
    else if (step.num === proj.currentStep && !PBL_FORUM_ACTIVE) cls = 'active';
    html += '<div class="pbl-step-item ' + cls + '" onclick="goToPBLStep(' + step.num + ')">';
    html += '<span class="pbl-step-num">' + (step.num < proj.currentStep ? '✓' : step.num) + '</span>';
    html += '<span class="pbl-step-label">' + step.label + '</span>';
    html += '</div>';
  });
  // Forum tab
  var forumCls = PBL_FORUM_ACTIVE ? ' active' : '';
  html += '<div class="pbl-step-item forum-tab' + forumCls + '" id="forumTab" onclick="goToPBLForum()">';
  html += '<span class="pbl-step-num">💬</span>';
  html += '<span class="pbl-step-label">Discussion</span>';
  html += '</div>';
  html += '</div>';
  
  // Step content
  html += '<div id="pblStepContent">';
  if (PBL_FORUM_ACTIVE) {
    html += '';
  } else {
    html += renderPBLStepContent(chKey, proj, data, proj.currentStep);
  }
  html += '</div>';
  
  area.innerHTML = html;
  
  // Render forum content if forum active
  if (PBL_FORUM_ACTIVE) {
    var sc = document.getElementById('pblStepContent');
    if (sc) renderPBLForum(sc);
  }
}


function showToast(msg, duration) {
  duration = duration || 2000;
  var toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;top:24px;left:50%;transform:translateX(-50%);background:rgba(15,39,68,0.92);color:#fff;padding:12px 24px;border-radius:10px;font-size:14px;font-weight:500;z-index:20000;opacity:0;transition:all 0.25s ease;pointer-events:none;box-shadow:0 8px 24px rgba(0,0,0,0.2);';
  toast.textContent = msg;
  document.body.appendChild(toast);
  requestAnimationFrame(function() {
    toast.style.opacity = '1';
    toast.style.transform = 'translateX(-50%) translateY(0)';
  });
  toast.style.transform = 'translateX(-50%) translateY(-10px)';
  setTimeout(function() {
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(-50%) translateY(-10px)';
    setTimeout(function() { if (toast.parentNode) toast.remove(); }, 300);
  }, duration);
}

function goToPBLStep(stepNum) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  
  if (stepNum > proj.currentStep) {
    showToast('Complete the previous step first to unlock this step.');
    return;
  }
  proj.currentStep = stepNum;
  savePBLProject(chKey);
  
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStepContent(chKey, proj, data, stepNum);
  }
  
  // Update step nav styles
  document.querySelectorAll('.pbl-step-item').forEach(function(item, idx) {
    var n = idx + 1;
    item.classList.remove('active', 'completed');
    if (n < proj.currentStep) item.classList.add('completed');
    else if (n === proj.currentStep) item.classList.add('active');
  });
}

function renderPBLStepContent(chKey, proj, data, stepNum) {
  switch(stepNum) {
    case 1: return renderPBLStep1(chKey, proj, data);
    case 2: return renderPBLStep2(chKey, proj, data);
    case 3: return renderPBLStep3(chKey, proj, data);
    case 4: return renderPBLStep4(chKey, proj, data);
    case 5: return renderPBLStep5(chKey, proj, data);
    case 6: return renderPBLStep6(chKey, proj, data);
    default: return '<p>Step not found</p>';
  }
}

function renderPBLStep1(chKey, proj, data) {
  var s = data.scenario;
  var html = '';
  html += '<div class="scenario-visual"><span class="scenario-icon">' + s.icon + '</span></div>';
  html += '<div class="scenario-box">';
  html += '<h3>' + s.title + '</h3>';
  s.text.split('\n\n').forEach(function(p) {
    html += '<p>' + p + '</p>';
  });
  html += '</div>';
  
  html += '<div class="pbl-action-bar">';
  html += '<span class="text-sm text-muted">Step 1 of 6 — Scenario Entry</span>';
  html += '<button class="btn btn-primary" onclick="nextPBLStep()">I\'m Ready to Start \u2192</button>';
  html += '</div>';
  return html;
}

function renderPBLStep2(chKey, proj, data) {
  var t = data.task;
  var html = '';
  html += '<div class="card"><div class="card-header"><div class="card-title">Project Role & Mission</div></div><div class="card-body">';
  html += '<p style="font-size:13.5px; line-height:1.6; color:var(--text-secondary);">';
  html += '<strong style="color:var(--text-primary);">Your Role:</strong> ' + t.role + '</p>';
  html += '</div></div>';
  
  html += '<div class="card"><div class="card-header"><div class="card-title">Deliverables</div></div><div class="card-body">';
  t.deliverables.forEach(function(d) {
    html += '<div class="task-deliverable">';
    html += '<h4>' + d.icon + ' ' + d.name + '</h4>';
    html += '<p>' + d.desc + '</p>';
    html += '</div>';
  });
  html += '</div></div>';
  
  html += '<div class="card"><div class="card-header"><div class="card-title">Evaluation Rubric</div></div><div class="card-body">';
  html += '<table class="rubric-table">';
  html += '<thead><tr><th>Dimension</th><th>Description</th><th class="rubric-weight">Weight</th></tr></thead>';
  html += '<tbody>';
  t.rubric.forEach(function(r) {
    html += '<tr><td><strong>' + r.dimension + '</strong></td><td>' + r.desc + '</td><td class="rubric-weight">' + r.weight + '%</td></tr>';
  });
  html += '</tbody></table>';
  html += '</div></div>';
  
    // Knowledge Map detailed instructions
  html += '<div class="card"><div class="card-header"><div class="card-title">A. What is a Knowledge Map?</div></div><div class="card-body">';
  html += '<p style="font-size:13px; line-height:1.6; color:var(--text-secondary); margin-bottom:12px;">';
  html += 'A <strong>knowledge map</strong> (or concept map) is a visual tool that represents key ideas as nodes (boxes/circles) and the relationships between them as labeled connecting lines. ';
  html += 'It helps you organize your understanding, identify gaps, and see how concepts connect to form a larger picture.';
  html += '</p>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Requirements Checklist</h4>';
  html += '<ul style="font-size:12.5px; line-height:1.7; color:var(--text-secondary); list-style:none; padding:0; margin-bottom:14px;">';
  html += '<li>&#9989; Minimum 8 core concept nodes</li>';
  html += '<li>&#9989; Minimum 10 connecting links with relationship labels</li>';
  html += '<li>&#9989; All key concepts from this chapter included</li>';
  html += '<li>&#9989; Hierarchical structure (main idea &#8594; sub-concepts &#8594; examples)</li>';
  html += '<li>&#9989; Clear, meaningful relationship descriptions on links</li>';
  html += '</ul>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Scoring Rubric</h4>';
  html += '<table class="rubric-table" style="margin-bottom:14px;">';
  html += '<thead><tr><th>Criterion</th><th class="rubric-weight">Weight</th><th>What We Look For</th></tr></thead>';
  html += '<tbody>';
  html += '<tr><td><strong>Structural Completeness</strong></td><td class="rubric-weight">40%</td><td style="font-size:12px;">Number of nodes, variety of links, clear hierarchical organization</td></tr>';
  html += '<tr><td><strong>Concept Accuracy</strong></td><td class="rubric-weight">30%</td><td style="font-size:12px;">Correct definitions, proper use of terminology, chapter concepts applied accurately</td></tr>';
  html += '<tr><td><strong>Connection Quality</strong></td><td class="rubric-weight">30%</td><td style="font-size:12px;">Meaningful relationship labels, logical connections, cross-links show deep understanding</td></tr>';
  html += '</tbody></table>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Suggested Core Concepts</h4>';
  html += '<div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:14px;">';
  (data.suggestedConcepts || []).slice(0, 10).forEach(function(c) {
    html += '<span class="suggested-concept">' + c + '</span>';
  });
  html += '</div>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Quick Example</h4>';
  html += '<div style="background:#f8fafc; border-radius:6px; padding:12px; font-size:12px; color:var(--text-secondary); line-height:1.6;">';
  html += '<strong>Main Concept:</strong> Critical Thinking<br>';
  html += '&nbsp;&nbsp;&#8627; <em>requires</em> &#8594; Clarity (e.g., clear definitions)<br>';
  html += '&nbsp;&nbsp;&#8627; <em>requires</em> &#8594; Accuracy (e.g., verified facts)<br>';
  html += '&nbsp;&nbsp;&#8627; <em>is hindered by</em> &#8594; Barriers (e.g., egocentrism)<br>';
  html += '&nbsp;&nbsp;&nbsp;&nbsp;&#8627; <em>type of</em> &#8594; Wishful Thinking';
  html += '</div>';
  html += '</div></div>';

  // Report detailed instructions
  html += '<div class="card"><div class="card-header"><div class="card-title">B. How to Write Your Critical Analysis Report</div></div><div class="card-body">';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Report Structure</h4>';
  html += '<div style="display:flex; gap:8px; margin-bottom:14px; flex-wrap:wrap;">';
  html += '<div style="flex:1; min-width:140px; background:#f8fafc; border-radius:6px; padding:10px; text-align:center;">';
  html += '<div style="font-size:11px; color:var(--text-muted); margin-bottom:4px;">Introduction</div>';
  html += '<div style="font-size:18px; font-weight:700; color:var(--accent);">30-50</div>';
  html += '<div style="font-size:10px; color:var(--text-muted);">words</div>';
  html += '</div>';
  html += '<div style="flex:2; min-width:180px; background:#f8fafc; border-radius:6px; padding:10px; text-align:center;">';
  html += '<div style="font-size:11px; color:var(--text-muted); margin-bottom:4px;">Analysis (3 paragraphs)</div>';
  html += '<div style="font-size:18px; font-weight:700; color:var(--success);">80-180</div>';
  html += '<div style="font-size:10px; color:var(--text-muted);">words - each = Claim + Evidence + Reasoning</div>';
  html += '</div>';
  html += '<div style="flex:1; min-width:140px; background:#f8fafc; border-radius:6px; padding:10px; text-align:center;">';
  html += '<div style="font-size:11px; color:var(--text-muted); margin-bottom:4px;">Conclusion</div>';
  html += '<div style="font-size:18px; font-weight:700; color:var(--warning);">40-70</div>';
  html += '<div style="font-size:10px; color:var(--text-muted);">words</div>';
  html += '</div>';
  html += '</div>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Report Template</h4>';
  html += '<div style="background:#f8fafc; border-left:3px solid var(--accent); border-radius:4px; padding:12px; font-size:11.5px; font-family:monospace; color:var(--text-secondary); line-height:1.7; margin-bottom:14px;">';
  html += '<strong style="color:var(--primary);">Introduction:</strong><br>';
  html += 'In the [case/scenario], the key issue is _____. <br>';
  html += 'This report will analyze _____ using critical thinking standards.<br><br>';
  html += '<strong style="color:var(--primary);">Analysis:</strong><br>';
  html += 'First, [dimension 1] - _____. The evidence shows that _____, which means _____.<br>';
  html += 'Second, [dimension 2] - _____. The data suggests _____, therefore _____.<br>';
  html += 'Third, [dimension 3] - _____. While some argue _____, a critical evaluation shows _____.<br><br>';
  html += '<strong style="color:var(--primary);">Conclusion:</strong><br>';
  html += 'In summary, _____. Based on the analysis above, I recommend _____.';
  html += '</div>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Strong vs. Weak Examples</h4>';
  html += '<div style="display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:14px;">';
  html += '<div style="background:#eafaf1; border-radius:6px; padding:10px;">';
  html += '<div style="font-size:11px; font-weight:600; color:var(--success); margin-bottom:4px;">&#10003; Strong</div>';
  html += '<div style="font-size:11.5px; color:var(--text-secondary); line-height:1.5;">"The CEO\'s claim that customers will not notice the battery gap lacks <strong>accuracy</strong> - QA data shows a 25% difference between advertised and actual battery life."</div>';
  html += '</div>';
  html += '<div style="background:#fdecec; border-radius:6px; padding:10px;">';
  html += '<div style="font-size:11px; font-weight:600; color:var(--danger); margin-bottom:4px;">&#10007; Weak</div>';
  html += '<div style="font-size:11.5px; color:var(--text-secondary); line-height:1.5;">"I think the CEO is wrong and we should delay the launch because it feels wrong."</div>';
  html += '</div>';
  html += '</div>';

  html += '<h4 style="font-size:13px; margin-bottom:8px; color:var(--text-primary);">Scoring Rubric</h4>';
  html += '<table class="rubric-table">';
  html += '<thead><tr><th>Criterion</th><th class="rubric-weight">Weight</th><th>What We Look For</th></tr></thead>';
  html += '<tbody>';
  html += '<tr><td><strong>Clarity</strong></td><td class="rubric-weight">15%</td><td style="font-size:12px;">Clear expression, precise language, well-structured</td></tr>';
  html += '<tr><td><strong>Accuracy</strong></td><td class="rubric-weight">20%</td><td style="font-size:12px;">Factual correctness, proper use of evidence and data</td></tr>';
  html += '<tr><td><strong>Logical Correctness</strong></td><td class="rubric-weight">25%</td><td style="font-size:12px;">Sound reasoning, valid conclusions, no fallacies</td></tr>';
  html += '<tr><td><strong>Relevance</strong></td><td class="rubric-weight">15%</td><td style="font-size:12px;">Stays focused, addresses the core issue</td></tr>';
  html += '<tr><td><strong>Completeness</strong></td><td class="rubric-weight">15%</td><td style="font-size:12px;">Thorough analysis, multiple perspectives considered</td></tr>';
  html += '<tr><td><strong>Fairness</strong></td><td class="rubric-weight">10%</td><td style="font-size:12px;">Balanced, acknowledges counterarguments</td></tr>';
  html += '</tbody></table>';

  html += '</div></div>';

  html += '<div class="pbl-action-bar">';
  html += '<button class="btn btn-outline" onclick="prevPBLStep()">\u2190 Back</button>';
  html += '<span class="text-sm text-muted">Step 2 of 6 \u2014 Project Task</span>';
  html += '<button class="btn btn-primary" onclick="nextPBLStep()">Start Working \u2192</button>';
  html += '</div>';
  return html;
}

function renderPBLStep3(chKey, proj, data) {
  var html = '';
  html += '<div class="card mb-16"><div class="card-header"><div class="card-title">Knowledge Inquiry & Scaffold Guidance</div></div><div class="card-body">';
  html += '<p class="text-sm text-secondary mb-12">These guiding questions will help you think through the project. Click each question to reveal scaffolded hints. The fewer hints you use, the higher your potential score!</p>';
  
  data.guidingQuestions.forEach(function(q) {
    var hintsUsed = proj.hintsUsed[q.id] || 0;
    html += '<div class="guiding-question" id="gq_' + q.id + '">';
    html += '<div class="gq-header" onclick="toggleGQ(\'' + q.id + '\')">';
    html += '<span class="gq-title">' + q.question + '</span>';
    html += '<span style="display:flex;align-items:center;">';
    if (hintsUsed > 0) html += '<span class="hint-used-badge">' + hintsUsed + ' hint' + (hintsUsed > 1 ? 's' : '') + ' used</span>';
    html += '<span class="gq-toggle" id="gqtoggle_' + q.id + '">\u25bc</span>';
    html += '</span>';
    html += '</div>';
    html += '<div class="gq-body" id="gqbody_' + q.id + '">';
    q.hints.forEach(function(hint, hi) {
      html += '<div class="hint-level">';
      html += '<div class="hint-level-label">Level ' + (hi + 1) + ' Hint</div>';
      if (hi < hintsUsed) {
        html += '<div class="hint-level-text">' + hint + '</div>';
      } else if (hi === hintsUsed) {
        html += '<button class="hint-level-btn" onclick="event.stopPropagation(); revealHint(\'' + q.id + '\', ' + hi + ')">Reveal Level ' + (hi + 1) + ' Hint</button>';
      } else {
        html += '<div class="hint-level-text" style="opacity:0.5; font-style:italic;">Complete previous hints first...</div>';
      }
      html += '</div>';
    });
    html += '</div></div>';
  });
  
  html += '</div></div>';
  
  html += '<div class="card"><div class="card-header"><div class="card-title">AI Tutor Support</div></div><div class="card-body">';
  html += '<p class="text-sm text-secondary mb-12">Need more personalized help? Open the AI Tutor and ask about this project. The tutor will guide your thinking using the Socratic method.</p>';
  html += '<button class="btn btn-accent" onclick="openAITutorFromData(this)" data-msg="Help me think through ' + data.title.replace(/"/g, '&quot;') + ' PBL project. I\'m working on ' + data.scenario.title.replace(/"/g, '&quot;') + '.">Open AI Tutor for Help</button>';
  html += '</div></div>';
  
  html += '<div class="pbl-action-bar">';
  html += '<button class="btn btn-outline" onclick="prevPBLStep()">&#8592; Back</button>';
  html += '<span class="text-sm text-muted">Step 3 of 6 — Knowledge Inquiry</span>';
  html += '<button class="btn btn-primary" onclick="nextPBLStep()">Start Building &#8594;</button>';
  html += '</div>';
  return html;
}

function toggleGQ(qId) {
  var body = document.getElementById('gqbody_' + qId);
  var toggle = document.getElementById('gqtoggle_' + qId);
  body.classList.toggle('open');
  toggle.classList.toggle('open');
}

function revealHint(qId, level) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  proj.hintsUsed[qId] = level + 1;
  savePBLProject(chKey);
  
  // Re-render step 3
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep3(chKey, proj, data);
  }
  // Keep the question expanded
  var body = document.getElementById('gqbody_' + qId);
  var toggle = document.getElementById('gqtoggle_' + qId);
  if (body) body.classList.add('open');
  if (toggle) toggle.classList.add('open');
}

var PBL_BUILD_TAB = 'concept-quiz';

function renderPBLStep4(chKey, proj, data) {
  var tab = PBL_BUILD_TAB;
  var html = '';
  
  html += '<div class="card"><div class="card-body">';
  html += '<div class="tabs">';
  html += '<div class="tab ' + (tab === 'concept-quiz' ? 'active' : '') + '" onclick="switchPBLBuildTab(\'concept-quiz\')">Concept Quiz</div>';
  html += '<div class="tab ' + (tab === 'report' ? 'active' : '') + '" onclick="switchPBLBuildTab(\'report\')">Report Editor</div>';
  html += '</div>';
  
  if (tab === 'concept-quiz') {
    html += renderConceptQuiz(chKey, proj, data);
  } else {
    html += renderReportEditor(chKey, proj, data);
  }
  
  html += '</div></div>';
  
  html += '<div class="pbl-action-bar">';
  html += '<button class="btn btn-outline" onclick="prevPBLStep()">&#8592; Back</button>';
  html += '<span class="text-sm text-muted">Step 4 of 6 — Iterative Polishing</span>';
  html += '<button class="btn btn-primary" onclick="nextPBLStep()">Continue to Submit &#8594;</button>';
  html += '</div>';
  return html;
}

function goToConceptQuiz() {
  var chKey = PBL_CURRENT_PROJECT;
  if (!chKey) return;
  
  // Ensure the project exists
  var proj = getPBLProject(chKey);
  if (!proj) return;
  
  // If not on step 4 yet, go there first (but allow going backward too)
  if (proj.currentStep < 4) {
    proj.currentStep = 4;
    savePBLProject(chKey);
  }
  
  // Set tab to concept quiz
  PBL_BUILD_TAB = 'concept-quiz';
  
  // Render step 4 with concept quiz tab
  var data = getPBLDisplayData(chKey);
  var contentEl = document.getElementById('pblStepContent');
  if (contentEl) {
    contentEl.innerHTML = renderPBLStep4(chKey, proj, data);
  }
  
  // Update step nav
  document.querySelectorAll('.pbl-step-item').forEach(function(item, idx) {
    var n = idx + 1;
    item.classList.remove('active', 'completed');
    if (n < 4) item.classList.add('completed');
    else if (n === 4) item.classList.add('active');
  });
  
  // Scroll to top
  var contentArea = document.querySelector('.content-area');
  if (contentArea) contentArea.scrollTop = 0;
}

function switchPBLBuildTab(tabName) {
  PBL_BUILD_TAB = tabName;
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
}


