var CONCEPT_QUIZ_STATE = {
  questions: [],
  answers: {},
  submitted: false
};

function generateConceptQuiz(chKey) {
  var bank = CONCEPT_QUIZ_BANK[chKey] || CONCEPT_QUIZ_BANK.ch1;
  var shuffled = shuffle(bank.slice());
  return shuffled.slice(0, 5).map(function(q) {
    var correctText = q.options[q.correctIndex];
    var shuffledOptions = shuffle(q.options.slice());
    var newCorrectIndex = shuffledOptions.indexOf(correctText);
    return {
      question: q.question,
      options: shuffledOptions,
      correctIndex: newCorrectIndex,
      explanation: q.explanation
    };
  });
}

function renderConceptQuiz(chKey, proj, data) {
  var html = '';
  
  if (CONCEPT_QUIZ_STATE.currentChapter !== chKey || CONCEPT_QUIZ_STATE.questions.length === 0) {
    CONCEPT_QUIZ_STATE.questions = generateConceptQuiz(chKey);
    CONCEPT_QUIZ_STATE.answers = {};
    CONCEPT_QUIZ_STATE.submitted = false;
    CONCEPT_QUIZ_STATE.currentChapter = chKey;
  }
  
  var questions = CONCEPT_QUIZ_STATE.questions;
  var answers = CONCEPT_QUIZ_STATE.answers;
  var submitted = CONCEPT_QUIZ_STATE.submitted;
  var answeredCount = Object.keys(answers).length;
  
  html += '<div class="concept-quiz">';
  html += '<div style="margin-bottom:16px;">';
  html += '<h4 style="margin-bottom:4px;">Concept Quiz</h4>';
  html += '<p class="text-sm text-secondary">Test your understanding of core concepts from this chapter. Answer all 5 questions, then submit.</p>';
  html += '</div>';
  
  questions.forEach(function(q, qi) {
    var selectedIdx = answers[qi];
    var isCorrect = submitted && selectedIdx === q.correctIndex;
    
    html += '<div class="quiz-question-card">';
    html += '<div class="quiz-question-num">Question ' + (qi + 1) + ' of 5</div>';
    html += '<div class="quiz-question-text">' + q.question + '</div>';
    html += '<div class="quiz-options">';
    
    q.options.forEach(function(opt, oi) {
      var letter = String.fromCharCode(65 + oi);
      var optClass = 'quiz-option';
      if (submitted) {
        if (oi === q.correctIndex) optClass += ' correct';
        if (selectedIdx === oi && oi !== q.correctIndex) optClass += ' incorrect';
        optClass += ' disabled';
      } else if (selectedIdx === oi) {
        optClass += ' selected';
      }
      
      var clickAttr = submitted ? '' : 'onclick="selectConceptQuizAnswer(' + qi + ', ' + oi + ')"';
      html += '<div class="' + optClass + '" ' + clickAttr + '>';
      html += '<div class="quiz-option-letter">' + letter + '</div>';
      html += '<div class="quiz-option-text">' + opt + '</div>';
      html += '</div>';
    });
    
    html += '</div>';
    
    if (submitted) {
      html += '<div class="quiz-explanation">';
      html += '<strong>' + (isCorrect ? '&#10003; Correct!' : '&#10007; Incorrect') + '</strong><br>';
      html += q.explanation;
      html += '</div>';
    }
    
    html += '</div>';
  });
  
  html += '<div style="display:flex; gap:12px; margin-top:20px; align-items:center;">';
  if (submitted) {
    var correctCount = 0;
    questions.forEach(function(q, qi) {
      if (answers[qi] === q.correctIndex) correctCount++;
    });
    var scorePct = Math.round((correctCount / questions.length) * 100);
    html += '<div style="flex:1; display:flex; align-items:center; gap:12px;">';
    html += '<span style="font-size:24px; font-weight:700; color:' + (scorePct >= 60 ? '#27ae60' : '#e74c3c') + ';">' + scorePct + '%</span>';
    html += '<span class="text-sm text-secondary">' + correctCount + ' out of 5 correct</span>';
    html += '</div>';
    html += '<button class="btn btn-outline" onclick="resetConceptQuiz()">Reset Quiz</button>';
  } else {
    html += '<div style="flex:1;" class="text-sm text-secondary">' + answeredCount + ' of 5 answered</div>';
    var btnDisabled = answeredCount < 5 ? 'disabled style="opacity:0.5;cursor:not-allowed;"' : '';
    html += '<button class="btn btn-primary" onclick="submitConceptQuiz()" ' + btnDisabled + '>Submit All Answers</button>';
  }
  html += '</div>';
  
  html += '</div>';
  return html;
}

function selectConceptQuizAnswer(qi, oi) {
  if (CONCEPT_QUIZ_STATE.submitted) return;
  CONCEPT_QUIZ_STATE.answers[qi] = oi;
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
}

function submitConceptQuiz() {
  CONCEPT_QUIZ_STATE.submitted = true;
  // Save score to clozeScore (reuse old field)
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (proj) {
    var correctCount = 0;
    CONCEPT_QUIZ_STATE.questions.forEach(function(q, qi) {
      if (CONCEPT_QUIZ_STATE.answers[qi] === q.correctIndex) correctCount++;
    });
    var scorePct = Math.round((correctCount / CONCEPT_QUIZ_STATE.questions.length) * 100);
    proj.clozeScore = scorePct;
    
    var s = AppState.student;
    if (s.milestones && s.milestones[chKey]) {
      var ms = s.milestones[chKey];
      if (!ms.completeness) ms.completeness = {};
      ms.completeness.conceptQuiz = true;
    }
    saveStudent();
  }
  
  var proj2 = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj2, data);
  }
}

function resetConceptQuiz() {
  CONCEPT_QUIZ_STATE.questions = [];
  CONCEPT_QUIZ_STATE.answers = {};
  CONCEPT_QUIZ_STATE.submitted = false;
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
}

// ===== Knowledge Map Editor (preserved for backward compat) =====
var KMAP_STATE = {
  dragging: null,
  dragOffset: { x: 0, y: 0 },
  linking: false,
  linkStart: null,
  selectedNode: null
};

function renderKMapEditor(chKey, proj, data) {
  var km = proj.knowledgeMap || { nodes: [], links: [] };
  var concepts = data.suggestedConcepts || [];
  var addedConcepts = km.nodes.map(function(n) { return n.label; });
  
  var html = '';
  html += '<div class="kmap-editor">';
  
  // Canvas
  html += '<div style="flex:1; display:flex; flex-direction:column; gap:0;">';
  html += '<div class="kmap-toolbar">';
  html += '<span class="kmap-toolbar-title">Tools:</span>';
  html += '<button class="btn btn-sm btn-outline" onclick="addKMapNode(\'New Node\')">+ Add Node</button>';
  html += '<button class="btn btn-sm btn-outline" onclick="startKMapLink()">Link Nodes</button>';
  html += '<button class="btn btn-sm btn-outline" onclick="deleteSelectedNode()">Delete Selected</button>';
  html += '<button class="btn btn-sm btn-outline" onclick="clearKMap()">Clear All</button>';
  html += '<span style="margin-left:auto; font-size:11px; color:var(--text-muted);">' + km.nodes.length + ' nodes, ' + km.links.length + ' links</span>';
  html += '</div>';
  html += '<div class="kmap-canvas" id="kmapCanvas" onmousemove="kmapMouseMove(event)" onmouseup="kmapMouseUp(event)" onclick="kmapCanvasClick(event)">';
  
  // Links (SVG)
  html += '<svg id="kmapLinksSvg" style="position:absolute; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:1;">';
  km.links.forEach(function(link, li) {
    var fromNode = km.nodes.find(function(n) { return n.id === link.from; });
    var toNode = km.nodes.find(function(n) { return n.id === link.to; });
    if (fromNode && toNode) {
      var x1 = fromNode.x + 50, y1 = fromNode.y + 20;
      var x2 = toNode.x + 50, y2 = toNode.y + 20;
      html += '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="#3498db" stroke-width="2" stroke-dasharray="0"/>';
      // Label
      var mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
      if (link.label) {
        html += '<text x="' + mx + '" y="' + my + '" text-anchor="middle" font-size="10" fill="#5a6c7d" style="background:#fff;">' + link.label + '</text>';
      }
    }
  });
  html += '</svg>';
  
  // Nodes
  km.nodes.forEach(function(node) {
    var cls = 'kmap-node' + (node.core ? ' core-node' : '') + (KMAP_STATE.selectedNode === node.id ? ' selected' : '');
    html += '<div class="' + cls + '" style="left:' + node.x + 'px; top:' + node.y + 'px;" ';
    html += 'onmousedown="startDragNode(event, \'' + node.id + '\')" onclick="selectKMapNode(event, \'' + node.id + '\')">';
    html += node.label;
    html += '<div class="kmap-delete-btn" onclick="event.stopPropagation(); deleteKMapNode(\'' + node.id + '\')">&times;</div>';
    html += '</div>';
  });
  
  if (km.nodes.length === 0) {
    html += '<div style="position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); text-align:center; color:var(--text-muted);">';
    html += '<div style="font-size:48px; margin-bottom:8px;">\ud83d\udda8\ufe0f</div>';
    html += '<div style="font-size:13px;">Click "Add Node" or add concepts from the sidebar to start building your knowledge map</div>';
    html += '</div>';
  }
  
  html += '</div></div>'; // end canvas
  
  // Sidebar
  html += '<div class="kmap-sidebar">';
  html += '<div class="kmap-sidebar-section">';
  html += '<h4>Recommended Concepts</h4>';
  html += '<div style="display:flex; flex-wrap:wrap; gap:4px;">';
  concepts.forEach(function(c) {
    var added = addedConcepts.indexOf(c) !== -1;
    html += '<span class="suggested-concept ' + (added ? 'added' : '') + '" onclick="' + (added ? '' : 'addConceptNode(\'' + c.replace(/'/g, "\\'") + '\')') + '">' + c + '</span>';
  });
  html += '</div></div>';
  
  html += '<div class="kmap-sidebar-section">';
  html += '<h4>How to Use</h4>';
  html += '<ul style="font-size:11.5px; color:var(--text-secondary); line-height:1.6; padding-left:16px; margin:0;">';
  html += '<li>Drag nodes to position them</li>';
  html += '<li>Click a node to select it</li>';
  html += '<li>Use "Link Nodes" to connect two nodes</li>';
  html += '<li>Double-click a node to rename</li>';
  html += '<li>Add concepts from the list above</li>';
  html += '</ul>';
  html += '</div>';

  html += '<div class="kmap-sidebar-section collapsible-section">';
  html += '<div class="collapsible-header" onclick="toggleKMapTips()">';
  html += '<h4 style="margin:0;">\U0001f4a1 Map Building Tips</h4>';
  html += '<span id="kmapTipsToggle" style="font-size:11px; color:var(--text-muted);">&#9660;</span>';
  html += '</div>';
  html += '<div class="collapsible-body" id="kmapTipsBody" style="margin-top:8px;">';
  html += '<ul style="font-size:11.5px; color:var(--text-secondary); line-height:1.6; padding-left:16px; margin:0;">';
  html += '<li><strong>Tip 1:</strong> Start with the main concept in the center</li>';
  html += '<li><strong>Tip 2:</strong> Use linking words on the lines (e.g., "causes", "is a type of")</li>';
  html += '<li><strong>Tip 3:</strong> Group related concepts together</li>';
  html += '<li><strong>Tip 4:</strong> Cross-links show deeper understanding</li>';
  html += '</ul>';
  html += '</div>';
  html += '</div>';

  html += '</div>'; // end sidebar
  
  html += '</div>'; // end editor
  return html;
}

function addKMapNode(label) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.knowledgeMap) proj.knowledgeMap = { nodes: [], links: [] };
  
  var newNode = {
    id: 'node_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
    label: label,
    x: 50 + Math.random() * 200,
    y: 50 + Math.random() * 150,
    core: false
  };
  proj.knowledgeMap.nodes.push(newNode);
  savePBLProject(chKey);
  refreshKMapEditor();
}

function addConceptNode(concept) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.knowledgeMap) proj.knowledgeMap = { nodes: [], links: [] };
  
  // Check if already exists
  var exists = proj.knowledgeMap.nodes.some(function(n) { return n.label === concept; });
  if (exists) return;
  
  var newNode = {
    id: 'node_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
    label: concept,
    x: 50 + Math.random() * 200,
    y: 50 + Math.random() * 200,
    core: concept === 'Critical Thinking' || concept === 'Argument'
  };
  proj.knowledgeMap.nodes.push(newNode);
  savePBLProject(chKey);
  refreshKMapEditor();
}

function selectKMapNode(e, nodeId) {
  e.stopPropagation();
  KMAP_STATE.selectedNode = nodeId;
  refreshKMapEditor();
}

function kmapCanvasClick(e) {
  if (e.target.id === 'kmapCanvas' || e.target.tagName === 'svg') {
    KMAP_STATE.selectedNode = null;
    if (KMAP_STATE.linking) {
      KMAP_STATE.linking = false;
      KMAP_STATE.linkStart = null;
    }
    refreshKMapEditor();
  }
}

function startDragNode(e, nodeId) {
  e.preventDefault();
  if (KMAP_STATE.linking) {
    if (!KMAP_STATE.linkStart) {
      KMAP_STATE.linkStart = nodeId;
      return;
    } else if (KMAP_STATE.linkStart !== nodeId) {
      createKMapLink(KMAP_STATE.linkStart, nodeId);
      KMAP_STATE.linking = false;
      KMAP_STATE.linkStart = null;
      return;
    }
  }
  
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var node = proj.knowledgeMap.nodes.find(function(n) { return n.id === nodeId; });
  if (!node) return;
  
  KMAP_STATE.dragging = nodeId;
  var canvas = document.getElementById('kmapCanvas');
  var rect = canvas.getBoundingClientRect();
  KMAP_STATE.dragOffset = {
    x: e.clientX - rect.left - node.x,
    y: e.clientY - rect.top - node.y
  };
}

function kmapMouseMove(e) {
  if (!KMAP_STATE.dragging) return;
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var node = proj.knowledgeMap.nodes.find(function(n) { return n.id === KMAP_STATE.dragging; });
  if (!node) return;
  
  var canvas = document.getElementById('kmapCanvas');
  var rect = canvas.getBoundingClientRect();
  node.x = Math.max(0, e.clientX - rect.left - KMAP_STATE.dragOffset.x);
  node.y = Math.max(0, e.clientY - rect.top - KMAP_STATE.dragOffset.y);
  
  // Update node position live
  var nodeEl = document.querySelector('.kmap-node[style*="left:' + Math.round(node.x) + 'px"]');
  // Just refresh the whole thing for simplicity
  refreshKMapLinks();
}

function kmapMouseUp(e) {
  if (KMAP_STATE.dragging) {
    KMAP_STATE.dragging = null;
    savePBLProject(PBL_CURRENT_PROJECT);
    refreshKMapEditor();
  }
}

function startKMapLink() {
  KMAP_STATE.linking = true;
  KMAP_STATE.linkStart = null;
  alert('Click the first node, then click the second node to create a link.');
}

function createKMapLink(fromId, toId) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.knowledgeMap) proj.knowledgeMap = { nodes: [], links: [] };
  
  // Check if link already exists
  var exists = proj.knowledgeMap.links.some(function(l) {
    return (l.from === fromId && l.to === toId) || (l.from === toId && l.to === fromId);
  });
  if (exists) return;
  
  var label = prompt('Enter a label for this link (optional):', '');
  proj.knowledgeMap.links.push({
    from: fromId,
    to: toId,
    label: label || ''
  });
  savePBLProject(chKey);
  refreshKMapEditor();
}

function deleteKMapNode(nodeId) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.knowledgeMap) return;
  
  proj.knowledgeMap.nodes = proj.knowledgeMap.nodes.filter(function(n) { return n.id !== nodeId; });
  proj.knowledgeMap.links = proj.knowledgeMap.links.filter(function(l) { return l.from !== nodeId && l.to !== nodeId; });
  
  if (KMAP_STATE.selectedNode === nodeId) KMAP_STATE.selectedNode = null;
  savePBLProject(chKey);
  refreshKMapEditor();
}

function deleteSelectedNode() {
  if (KMAP_STATE.selectedNode) {
    deleteKMapNode(KMAP_STATE.selectedNode);
  }
}

function toggleKMapTips() {
  var body = document.getElementById('kmapTipsBody');
  var toggle = document.getElementById('kmapTipsToggle');
  if (body) {
    if (body.style.display === 'none') {
      body.style.display = 'block';
      if (toggle) toggle.textContent = '\u25bc';
    } else {
      body.style.display = 'none';
      if (toggle) toggle.textContent = '\u25b6';
    }
  }
}

function clearKMap() {
  if (!confirm('Clear all nodes and links? This cannot be undone.')) return;
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  proj.knowledgeMap = { nodes: [], links: [] };
  KMAP_STATE.selectedNode = null;
  savePBLProject(chKey);
  refreshKMapEditor();
}

function refreshKMapEditor() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var data = getPBLDisplayData(chKey);
  PBL_BUILD_TAB = 'kmap';
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
}

function refreshKMapLinks() {
  // Lightweight refresh of just the SVG links
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var km = proj.knowledgeMap;
  var svg = document.getElementById('kmapLinksSvg');
  if (!svg || !km) return;
  
  var linksHtml = '';


  km.links.forEach(function(link) {
    var fromNode = km.nodes.find(function(n) { return n.id === link.from; });
    var toNode = km.nodes.find(function(n) { return n.id === link.to; });
    if (fromNode && toNode) {
      var x1 = fromNode.x + 50, y1 = fromNode.y + 20;
      var x2 = toNode.x + 50, y2 = toNode.y + 20;
      linksHtml += '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="#3498db" stroke-width="2"/>';
      if (link.label) {
        var mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
        linksHtml += '<text x="' + mx + '" y="' + my + '" text-anchor="middle" font-size="10" fill="#5a6c7d">' + link.label + '</text>';
      }
    }
  });
  svg.innerHTML = linksHtml;
}

// ===== Report Editor =====
function renderReportEditor(chKey, proj, data) {
  // Initialize report sections if not exists
  if (!proj.reportSections) {
    proj.reportSections = {
      topicSentence: '',
      explanation: '',
      examples: '',
      concludingSentence: ''
    };
    // Try to populate from latest draft
    var drafts = proj.reportDrafts || [];
    if (drafts.length > 0) {
      var latest = drafts[drafts.length - 1].text;
      proj.reportSections.explanation = latest; // put everything in explanation as fallback
    }
  }
  
  var sec = proj.reportSections;
  var fullText = buildFullReport(sec);
  var wordCount = fullText.trim() ? fullText.trim().split(/\s+/).length : 0;
  var minWords = 150, maxWords = 400;
  var pct = Math.min(100, Math.max(0, (wordCount / minWords) * 100));
  var fillClass = wordCount < minWords ? 'under' : (wordCount > maxWords ? 'over' : '');
  var drafts = proj.reportDrafts || [];

  var html = '';
  html += '<div class="report-editor-container">';

  // Header
  html += '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;">';
  html += '<div style="font-size:14px; font-weight:700;">Structured Analysis Report</div>';
  html += '<div style="font-size:12px; color:var(--text-muted);">Target: ' + minWords + '-' + maxWords + ' words</div>';
  html += '</div>';

  // Word count bar
  html += '<div class="word-count-bar">';
  html += '<span class="word-count-text">' + wordCount + ' words</span>';
  html += '<div class="word-count-track"><div class="word-count-fill ' + fillClass + '" style="width:' + pct + '%;"></div></div>';
  html += '<span class="word-count-text">' + (wordCount < minWords ? (minWords - wordCount) + ' more needed' : (wordCount > maxWords ? (wordCount - maxWords) + ' over limit' : 'Good length')) + '</span>';
  html += '</div>';

  // Section 1: Topic Sentence
  html += '<div class="report-section">';
  html += '<div class="report-section-title">';
  html += '<strong>1. Topic Sentence</strong>';
  html += '<span class="report-section-hint">1-2 sentences. State your core claim or thesis clearly.</span>';
  html += '</div>';
  html += '<textarea class="report-textarea-sm" id="sec_topicSentence" placeholder="e.g. Jaguar\'s all-electric rebrand represents a high-stakes strategic gamble that risks alienating its core customer base..." oninput="onReportSectionInput(\'topicSentence\')">' + escapeHtml(sec.topicSentence || '') + '</textarea>';
  html += '</div>';

  // Section 2: Explanation
  html += '<div class="report-section">';
  html += '<div class="report-section-title">';
  html += '<strong>2. Explanation & Reasoning</strong>';
  html += '<span class="report-section-hint">Explain your reasoning. What logical principles or critical thinking standards support your claim?</span>';
  html += '</div>';
  html += '<textarea class="report-textarea" id="sec_explanation" placeholder="Explain the logic behind your thesis. Consider: What premises support your conclusion? What intellectual standards (clarity, accuracy, depth, relevance) are at play here?..." oninput="onReportSectionInput(\'explanation\')">' + escapeHtml(sec.explanation || '') + '</textarea>';
  html += '</div>';

  // Section 3: Examples
  html += '<div class="report-section">';
  html += '<div class="report-section-title">';
  html += '<strong>3. Examples & Evidence</strong>';
  html += '<span class="report-section-hint">Provide specific evidence, examples, or data from the case to support your argument.</span>';
  html += '</div>';
  html += '<textarea class="report-textarea" id="sec_examples" placeholder="Give 2-3 specific examples from the scenario that support your analysis. For instance: Sales figures, customer reactions, competitor behavior, brand history..." oninput="onReportSectionInput(\'examples\')">' + escapeHtml(sec.examples || '') + '</textarea>';
  html += '</div>';

  // Section 4: Concluding Sentence
  html += '<div class="report-section">';
  html += '<div class="report-section-title">';
  html += '<strong>4. Concluding Sentence</strong>';
  html += '<span class="report-section-hint">Wrap up your argument. Restate your thesis in light of the evidence presented.</span>';
  html += '</div>';
  html += '<textarea class="report-textarea-sm" id="sec_concludingSentence" placeholder="e.g. In sum, while the rebrand is bold and forward-looking, it underestimates the value of Jaguar\'s heritage and risks..." oninput="onReportSectionInput(\'concludingSentence\')">' + escapeHtml(sec.concludingSentence || '') + '</textarea>';
  html += '</div>';

  // Generate full report button + preview
  html += '<div style="display:flex; gap:8px; margin-top:16px; margin-bottom:12px;">';
  html += '<button class="btn btn-sm btn-accent" onclick="generateFullReport()">Generate Full Report & Save Draft</button>';
  html += '<button class="btn btn-sm btn-outline" onclick="submitReportVersion()">Submit Final Version</button>';
  html += '<span style="margin-left:auto; font-size:11px; color:var(--text-muted); align-self:center;">' + drafts.length + ' versions saved</span>';
  html += '</div>';

  // Full report preview
  html += '<div id="fullReportPreview">';
  if (wordCount > 0) {
    html += '<div style="font-size:12px; font-weight:600; color:var(--text-secondary); margin-bottom:6px;">Full Report Preview</div>';
    html += '<div class="report-preview">' + formatReportPreview(fullText) + '</div>';
  }
  html += '</div>';

  // Writing tips
  html += '<div class="card" style="margin-top:16px;">';
  html += '<div class="card-header" style="cursor:pointer;" onclick="toggleReportTips()">';
  html += '<div class="card-title" style="display:flex; align-items:center; gap:8px;">💡 Writing Tips <span id="reportTipsToggle" style="font-size:11px; color:var(--text-muted);">Click to expand</span></div>';
  html += '</div>';
  html += '<div class="card-body" id="reportTipsBody" style="display:none;">';
  html += '<ul style="font-size:12px; color:var(--text-secondary); line-height:1.7; padding-left:18px; margin:0;">';
  html += '<li><strong>Topic Sentence:</strong> Make it arguable — someone should be able to disagree with it.</li>';
  html += '<li><strong>Explanation:</strong> Use chapter concepts explicitly (validity, soundness, barriers, standards).</li>';
  html += '<li><strong>Examples:</strong> Be specific. Name names, cite evidence, reference the scenario details.</li>';
  html += '<li><strong>Concluding:</strong> Don\'t just repeat — synthesize. Show how the evidence supports the claim.</li>';
  html += '<li>Aim for 150-400 words total across all four sections.</li>';
  html += '</ul>';
  html += '</div></div>';

  // Version history
  if (drafts.length > 0) {
    html += '<div class="card" style="margin-top:16px;">';
    html += '<div class="card-header"><div class="card-title">Version History</div></div><div class="card-body">';
    html += '<div class="version-history">';
    drafts.slice().reverse().forEach(function(draft, idx) {
      var verNum = drafts.length - idx;
      var isCurrent = idx === 0;
      var draftWords = draft.text.trim() ? draft.text.trim().split(/\s+/).length : 0;
      var dateStr = new Date(draft.timestamp).toLocaleString();
      html += '<div class="version-item ' + (isCurrent ? 'current' : '') + '" onclick="loadReportVersion(' + (verNum - 1) + ')">';
      html += '<div><span class="version-label">Version ' + verNum + '</span>';
      if (isCurrent) html += ' <span style="font-size:10px; background:var(--success); color:#fff; padding:1px 6px; border-radius:8px;">Current</span>';
      html += '<div class="version-meta">' + draftWords + ' words</div></div>';
      html += '<span class="version-meta">' + dateStr + '</span>';
      html += '</div>';
    });
    html += '</div></div></div>';
  }

  html += '</div>';
  return html;
}

function escapeHtml(text) {
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
}

function buildFullReport(sec) {
  var parts = [];
  if (sec.topicSentence && sec.topicSentence.trim()) parts.push(sec.topicSentence.trim());
  if (sec.explanation && sec.explanation.trim()) parts.push(sec.explanation.trim());
  if (sec.examples && sec.examples.trim()) parts.push(sec.examples.trim());
  if (sec.concludingSentence && sec.concludingSentence.trim()) parts.push(sec.concludingSentence.trim());
  return parts.join(' ');
}

function formatReportPreview(text) {
  if (!text || !text.trim()) return '';
  return text;
}

function onReportSectionInput(sectionName) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.reportSections) proj.reportSections = {};
  
  var ta = document.getElementById('sec_' + sectionName);
  if (ta) {
    proj.reportSections[sectionName] = ta.value;
  }
  
  savePBLProject(chKey);
  
  // Update preview
  var fullText = buildFullReport(proj.reportSections);
  var wordCount = fullText.trim() ? fullText.trim().split(/\s+/).length : 0;
  var preview = document.getElementById('fullReportPreview');
  if (preview) {
    preview.innerHTML = '<div style="font-size:12px; font-weight:600; color:var(--text-secondary); margin-bottom:6px;">Full Report Preview (' + wordCount + ' words)</div>' +
      '<div class="report-preview">' + fullText + '</div>';
  }
  
  // Update word count bar if exists
  var wordCountText = document.querySelector('.word-count-text');
  // (visual only - full bar update skipped for simplicity)
}

function generateFullReport() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.reportSections) proj.reportSections = {};
  
  var fullText = buildFullReport(proj.reportSections);
  
  if (!fullText.trim()) {
    showToast('Please write some content first.');
    return;
  }
  
  // Save as draft
  if (!proj.reportDrafts) proj.reportDrafts = [];
  proj.reportDrafts.push({
    text: fullText,
    timestamp: Date.now()
  });
  
  savePBLProject(chKey);
  
  // Refresh view
  var content = document.getElementById('pblStepContent');
  if (content) {
    var data = getPBLDisplayData(chKey);
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
  
  showToast('Full report generated and saved as draft.');
}

function toggleReportTips() {
  var body = document.getElementById('reportTipsBody');
  var toggle = document.getElementById('reportTipsToggle');
  if (body) {
    if (body.style.display === 'none') {
      body.style.display = 'block';
      if (toggle) toggle.textContent = '\u25bc';
    } else {
      body.style.display = 'none';
      if (toggle) toggle.textContent = '\u25b6';
    }
  }
}

function onReportInput() {
  var textarea = document.getElementById('reportTextarea');
  if (!textarea) return;
  // Just update the word count display live
  var text = textarea.value;
  var wordCount = text.trim() ? text.trim().split(/\s+/).length : 0;
  // Auto-save every 3 seconds (debounced)
  if (window._reportSaveTimer) clearTimeout(window._reportSaveTimer);
  window._reportSaveTimer = setTimeout(function() {
    saveReportDraft(true);
  }, 3000);
}

function saveReportDraft(silent) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var textarea = document.getElementById('reportTextarea');
  if (!textarea) return;
  
  var text = textarea.value;
  
  if (!proj.reportDrafts) proj.reportDrafts = [];
  
  if (proj.reportDrafts.length === 0) {
    proj.reportDrafts.push({ text: text, timestamp: Date.now(), version: 1 });
  } else {
    // Update last draft
    var last = proj.reportDrafts[proj.reportDrafts.length - 1];
    last.text = text;
    last.timestamp = Date.now();
  }
  
  savePBLProject(chKey);
  if (!silent) {
    // Brief visual feedback
    var btn = event && event.target;
    if (btn) {
      var orig = btn.textContent;
      btn.textContent = 'Saved!';
      setTimeout(function() { btn.textContent = orig; }, 1000);
    }
  }
}

function submitReportVersion() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var textarea = document.getElementById('reportTextarea');
  if (!textarea) return;
  
  var text = textarea.value;
  if (!text.trim()) { alert('Write some content first!'); return; }
  
  if (!proj.reportDrafts) proj.reportDrafts = [];
  if (proj.reportDrafts.length >= 5) {
    if (!confirm('You have 5 versions already. Submitting a new one will replace the oldest version. Continue?')) return;
    proj.reportDrafts.shift();
  }
  
  proj.reportDrafts.push({
    text: text,
    timestamp: Date.now(),
    version: proj.reportDrafts.length + 1
  });
  proj.iterations = (proj.iterations || 0) + 1;
  savePBLProject(chKey);
  
  PBL_BUILD_TAB = 'report';
  var content = document.getElementById('pblStepContent');
  var data = getPBLDisplayData(chKey);
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
}

function loadReportVersion(idx) {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.reportDrafts || !proj.reportDrafts[idx]) return;
  
  var textarea = document.getElementById('reportTextarea');
  if (textarea) {
    textarea.value = proj.reportDrafts[idx].text;
    textarea.focus();
  }
}

function getAIFeedback() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  var textarea = document.getElementById('reportTextarea');
  if (!textarea) return;
  
  var text = textarea.value;
  var wordCount = text.trim() ? text.trim().split(/\s+/).length : 0;
  
  if (wordCount < 50) {
    alert('Write at least 50 words first so I can give meaningful feedback!');
    return;
  }
  
  // Generate rule-driven feedback
  var feedback = generateAIFeedbackText(text, wordCount, chKey);
  proj.aiFeedback = feedback;
  savePBLProject(chKey);
  
  PBL_BUILD_TAB = 'report';
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep4(chKey, proj, data);
  }
}

function generateAIFeedbackText(text, wordCount, chKey) {
  var data = getPBLDisplayData(chKey);
  var suggestions = [];
  var strengths = [];
  
  // Word count check
  if (wordCount >= 150 && wordCount <= 300) {
    strengths.push('Good length — your report is within the 150-300 word target range.');
  } else if (wordCount < 150) {
    suggestions.push('Your report is currently ' + wordCount + ' words. Try to expand to at least 150 words by adding more specific examples and deeper analysis.');
  } else {
    suggestions.push('Your report is ' + wordCount + ' words, which exceeds the 300-word target. Consider tightening your arguments and being more concise.');
  }
  
  // Keyword/concept coverage
  var ch1Concepts = ['critical thinking', 'clarity', 'accuracy', 'relevance', 'consistency', 'logical', 'completeness', 'fairness', 'barrier', 'egocentr', 'bias', 'decision'];
  var ch2Concepts = ['argument', 'premise', 'conclusion', 'indicator', 'statement', 'rhetoric', 'evidence', 'authority', 'fallacy', 'logical', 'premise', 'conditional'];
  var targetConcepts = chKey === 'ch1' ? ch1Concepts : ch2Concepts;
  
  var lowerText = text.toLowerCase();
  var foundConcepts = targetConcepts.filter(function(c) { return lowerText.indexOf(c) !== -1; });
  var conceptScore = Math.min(10, (foundConcepts.length / targetConcepts.length) * 10);
  
  if (foundConcepts.length >= 5) {
    strengths.push('Strong concept coverage — you\'ve incorporated ' + foundConcepts.length + ' key concepts from Chapter ' + (chKey === 'ch1' ? '1' : '2') + '.');
  } else {
    suggestions.push('Try incorporating more key concepts from the chapter. You currently use about ' + foundConcepts.length + ' major concepts — aim for 5+ to show deep understanding.');
  }
  
  // Structure check
  var sentences = text.split(/[.!?]+/).filter(function(s) { return s.trim().length > 5; });
  if (sentences.length >= 8) {
    strengths.push('Good sentence variety and structure with ' + sentences.length + ' substantive sentences.');
  } else {
    suggestions.push('Consider breaking your ideas into more sentences to improve clarity and readability.');
  }
  
  // Evidence check
  var evidenceWords = ['because', 'since', 'evidence', 'study', 'data', 'research', 'example', 'shows', 'demonstrates', 'according'];
  var evidenceCount = evidenceWords.filter(function(w) { return lowerText.indexOf(w) !== -1; }).length;
  if (evidenceCount >= 3) {
    strengths.push('You effectively use evidence indicators to support your claims.');
  } else {
    suggestions.push('Try to include more evidence-based reasoning. Use words like "because," "evidence shows," or "research indicates" to back up your claims.');
  }
  
  var html = '<strong>Strengths:</strong><ul>';
  strengths.forEach(function(s) { html += '<li>' + s + '</li>'; });
  html += '</ul>';
  
  if (suggestions.length > 0) {
    html += '<strong style="color:var(--warning);">Areas to Improve:</strong><ul>';
    suggestions.forEach(function(s) { html += '<li>' + s + '</li>'; });
    html += '</ul>';
  }
  
  html += '<strong>Overall:</strong> ';
  if (strengths.length >= 2 && suggestions.length <= 1) {
    html += 'Excellent work! Your analysis is well-structured and demonstrates strong critical thinking. Keep refining for an even higher score.';
  } else if (strengths.length >= suggestions.length) {
    html += 'Good start! You have a solid foundation. Focus on the areas above to strengthen your analysis further.';
  } else {
    html += 'You\'re on the right track. Review the suggestions above and revise your report to strengthen your critical analysis.';
  }
  
  return html;
}

// ===== Step 5: Submit & Gallery =====
function renderPBLStep5(chKey, proj, data) {
  var gallery = PBL_GALLERY_MOCK[chKey] || [];
  var hasSubmission = proj.submittedAt !== null;
  
  var html = '';
  html += '<div class="card mb-16"><div class="card-header"><div class="card-title">Your Final Submission</div><span class="text-sm text-muted">Complete the quiz and report in Step 4, then submit here</span></div><div class="card-body">';
  
  if (!hasSubmission) {
    html += '<div class="grid-2">';
    html += '<div>';
    html += '<h4 style="font-size:13px; margin-bottom:8px;">Concept Quiz</h4>';
    var quizData = proj.conceptQuiz || null;
    var quizScore = 0;
    var quizTotal = 0;
    var quizSubmitted = false;
    if (quizData && quizData.questions && quizData.questions.length > 0) {
      quizTotal = quizData.questions.length;
      quizScore = quizData.questions.filter(function(q) { return q.submitted && q.userAnswer === q.correctIndex; }).length;
      quizSubmitted = quizData.questions.some(function(q) { return q.submitted; });
    }
    // Also check clozeScore (legacy format from submitConceptQuiz)
    if (!quizSubmitted && proj.clozeScore !== null && proj.clozeScore !== undefined) {
      quizScore = Math.round(proj.clozeScore * 0.05);
      quizTotal = 5;
      quizSubmitted = true;
    }
    var quizPct = quizTotal > 0 ? Math.round(quizScore / quizTotal * 100) : 0;
    
    html += '<div style="background:var(--bg-page); border:1px solid var(--border); border-radius:8px; padding:20px; text-align:center;">';
    if (quizSubmitted) {
      html += '<div style="font-size:36px; font-weight:700; color:var(--success); margin-bottom:4px;">' + quizScore + '/' + quizTotal + '</div>';
      html += '<div style="font-size:12px; color:var(--text-muted); margin-bottom:12px;">' + quizPct + '% correct</div>';
      html += '<div style="height:8px; background:#e8ecf1; border-radius:4px; overflow:hidden; margin-bottom:12px;"><div style="height:100%; width:' + quizPct + '%; background:var(--success); border-radius:4px;"></div></div>';
      html += '<button class="btn btn-outline btn-sm" onclick="goToConceptQuiz()">Retake Quiz</button>';
    } else {
      html += '<div style="font-size:36px; margin-bottom:8px;">&#128221;</div>';
      html += '<div style="font-size:14px; font-weight:600; margin-bottom:4px; color:var(--text-primary);">Concept Quiz Required</div>';
      html += '<div style="font-size:11px; color:var(--text-muted); margin-bottom:12px; line-height:1.4;">Test your understanding of key concepts before submitting your final report. 5 questions, ~2 minutes.</div>';
      html += '<button class="btn btn-primary" style="width:100%;" onclick="goToConceptQuiz()">📝 Start Concept Quiz</button>';
    }
    html += '</div>';
    html += '<h4 style="font-size:13px; margin-bottom:8px;">Final Report</h4>';
    var drafts = proj.reportDrafts || [];
    var latest = drafts.length > 0 ? drafts[drafts.length - 1].text : '';
    var words = latest.trim() ? latest.trim().split(/\s+/).length : 0;
    html += '<div style="height:180px; background:#fafbfc; border:1px solid var(--border); border-radius:6px; padding:12px; font-size:11.5px; color:var(--text-secondary); overflow:hidden; line-height:1.5;">';
    html += latest ? latest.substring(0, 200) + (latest.length > 200 ? '...' : '') : 'No report written yet';
    html += '</div>';
    html += '<div style="font-size:11px; color:var(--text-muted); margin-top:4px;">' + words + ' words</div>';
    html += '<button class="btn btn-outline btn-sm" style="margin-top:8px; width:100%;" onclick="goToPBLStep(4); switchPBLBuildTab(\'report\');">✏️ Edit Report</button>';
    html += '</div></div>';
    
    html += '<div style="margin-top:16px; text-align:center;">';
    var quizDone = proj.conceptQuiz && proj.conceptQuiz.questions && proj.conceptQuiz.questions.some(function(q){ return q.submitted; });
  var canSubmit = quizDone && words >= 100;
    if (!canSubmit) {
      html += '<p class="text-sm text-warning mb-8">You need to complete the Concept Quiz and write at least 100 words in your report to submit.</p>';
    }
    html += '<button class="btn btn-success btn-lg" ' + (canSubmit ? '' : 'disabled') + ' onclick="submitPBLProject()">Submit for Evaluation</button>';
    html += '</div>';
  } else {
    html += '<div style="text-align:center; padding:20px;">';
    html += '<div style="font-size:48px; margin-bottom:10px;">\u2705</div>';
    html += '<h3 style="font-size:18px; margin-bottom:4px;">Submitted Successfully!</h3>';
    html += '<p class="text-sm text-secondary mb-12">Your project has been submitted. View the evaluation results in Step 6.</p>';
    html += '<div class="text-sm text-muted">Submitted: ' + new Date(proj.submittedAt).toLocaleString() + '</div>';
    html += '<div style="margin-top:12px;"><button class="btn btn-outline btn-sm" onclick="goToPBLStep(4); switchPBLBuildTab(\'report\');">View Report Details</button></div>';
    html += '</div>';
  }
  
  html += '</div></div>';
  
  // Gallery
  html += '<div class="card"><div class="card-header"><div class="card-title">Class Gallery</div>';
  html += '<span class="text-sm text-muted">' + gallery.length + ' student works</span></div><div class="card-body">';
  html += '<div class="gallery-grid">';
  gallery.forEach(function(item) {
    html += '<div class="gallery-item">';
    html += '<div class="gallery-thumb">' + item.icon + '</div>';
    html += '<div class="gallery-info">';
    html += '<div style="display:flex; justify-content:space-between; align-items:center;">';
    html += '<span class="gallery-author">' + item.author + '</span>';
    html += '<span class="gallery-score">' + item.score + '/10</span>';
    html += '</div>';
    html += '<div class="gallery-stats">';
    html += '<span>\u2764\ufe0f ' + item.likes + '</span>';
    html += '<span>\ud83d\udd04 ' + item.iterations + ' versions</span>';
    html += '</div></div></div>';
  });
  html += '</div></div></div>';
  
  html += '<div class="pbl-action-bar">';
  html += '<button class="btn btn-outline" onclick="prevPBLStep()">&#8592; Back</button>';
  html += '<span class="text-sm text-muted">Step 5 of 6 — Project Output</span>';
  html += '<button class="btn btn-primary" onclick="nextPBLStep()">View Evaluation &#8594;</button>';
  html += '</div>';
  return html;
}

function submitPBLProject() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  
  proj.submittedAt = Date.now();
  proj.finalReport = proj.reportDrafts && proj.reportDrafts.length > 0
    ? proj.reportDrafts[proj.reportDrafts.length - 1].text
    : '';
  proj.finalKnowledgeMap = JSON.parse(JSON.stringify(proj.knowledgeMap || { nodes: [], links: [] }));
  
  // Generate AI score
  var scoreData = calculatePBLAIScore(chKey, proj);
  proj.aiScore = scoreData.total;
  proj.aiFeedback = scoreData.feedback;
  proj.status = 'completed';
  
  savePBLProject(chKey);
  
  addMessage({
    type: 'success',
    title: 'PBL Project Submitted!',
    body: 'Your ' + getPBLDisplayData(chKey).title + ' project has been submitted. AI evaluation score: ' + scoreData.total.toFixed(1) + '/10. View the full evaluation in the project.'
  });
  
  // Re-render
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep5(chKey, proj, data);
  }
}

function calculatePBLAIScore(chKey, proj) {
  var data = getPBLDisplayData(chKey);
  var report = proj.finalReport || '';
  var km = proj.finalKnowledgeMap || proj.knowledgeMap || { nodes: [], links: [] };
  var wordCount = report.trim() ? report.trim().split(/\s+/).length : 0;
  var lowerText = report.toLowerCase();
  
  // Calculate scores per dimension (0-10)
  var scores = {};
  
  // Clarity: based on word count range and sentence structure
  var clarityScore = 5;
  if (wordCount >= 150 && wordCount <= 300) clarityScore = 8;
  if (wordCount >= 200 && wordCount <= 280) clarityScore = 9;
  var sentences = report.split(/[.!?]+/).filter(function(s){return s.trim().length>5;}).length;
  if (sentences >= 10) clarityScore = Math.min(10, clarityScore + 1);
  scores.clarity = clarityScore;
  
  // Accuracy: based on concept keyword coverage
  var targetConcepts = data.suggestedConcepts || [];
  var foundConcepts = targetConcepts.filter(function(c) {
    return lowerText.indexOf(c.toLowerCase()) !== -1;
  }).length;
  var accuracyScore = Math.min(10, Math.max(3, Math.round(foundConcepts / targetConcepts.length * 10) + 2));
  scores.accuracy = accuracyScore;
  
  // Logical Correctness: based on evidence/indicator words
  var evidenceWords = ['because', 'since', 'therefore', 'thus', 'hence', 'evidence', 'shows', 'demonstrates', 'conclude', 'reason'];
  var evCount = evidenceWords.filter(function(w) { return lowerText.indexOf(w) !== -1; }).length;
  var logicScore = Math.min(10, 3 + evCount);
  scores.logicalCorrectness = logicScore;
  
  // Relevance: based on scenario keywords match
  var scenarioKeywords = chKey === 'ch1'
    ? ['decision', 'launch', 'battery', 'product', 'critical', 'thinking']
    : ['argument', 'premise', 'conclusion', 'advertising', 'vita', 'rhetoric'];
  var relCount = scenarioKeywords.filter(function(w) { return lowerText.indexOf(w) !== -1; }).length;
  var relevanceScore = Math.min(10, 4 + relCount);
  scores.relevance = relevanceScore;
  
  // Completeness: based on knowledge map + report length + iterations
  var kmScore = Math.min(10, km.nodes.length * 1.5);
  var reportCompleteness = Math.min(10, wordCount / 30);
  var completenessScore = Math.round((kmScore + reportCompleteness) / 2);
  completenessScore = Math.min(10, Math.max(3, completenessScore));
  scores.completeness = completenessScore;
  
  // Fairness: based on balanced perspective words
  var fairWords = ['however', 'although', 'on the other hand', 'despite', 'while', 'both sides', 'balanced', 'counter'];
  var fairCount = fairWords.filter(function(w) { return lowerText.indexOf(w) !== -1; }).length;
  var fairnessScore = Math.min(10, 4 + fairCount);
  scores.fairness = fairnessScore;
  
  // Bonus: iteration bonus
  var iterBonus = Math.min(1, (proj.iterations || 0) * 0.2);
  
  // Penalty: hints used
  var totalHints = 0;
  Object.keys(proj.hintsUsed || {}).forEach(function(k) {
    totalHints += proj.hintsUsed[k] || 0;
  });
  var hintPenalty = Math.min(2, totalHints * 0.15);
  
  // Calculate total with rubric weights
  var rubric = data.task.rubric;
  var weightedSum = 0;
  var totalWeight = 0;
  rubric.forEach(function(r) {
    var dimKey = r.dimension.toLowerCase().replace(/\s+/g, '');
    // Map rubric dimension names to score keys
    var scoreKey = null;
    Object.keys(scores).forEach(function(k) {
      if (k.toLowerCase().indexOf(dimKey.substring(0, 4)) === 0) scoreKey = k;
    });
    if (!scoreKey && dimKey.indexOf('logical') === 0) scoreKey = 'logicalCorrectness';
    if (scoreKey) {
      weightedSum += scores[scoreKey] * r.weight;
      totalWeight += r.weight;
    }
  });
  
  var total = totalWeight > 0 ? weightedSum / totalWeight : 7;
  total = total + iterBonus - hintPenalty;
  total = Math.max(1, Math.min(10, total));
  total = Math.round(total * 10) / 10;
  
  // Generate feedback text
  var feedback = generateEvaluationFeedback(scores, total, proj, data);
  
  return { total: total, scores: scores, feedback: feedback };
}

function generateEvaluationFeedback(scores, total, proj, data) {
  var html = '<div style="font-size:12.5px; line-height:1.6; color:var(--text-secondary);">';
  
  html += '<p><strong>Overall Assessment:</strong> ';
  if (total >= 8.5) {
    html += 'Outstanding work! Your project demonstrates excellent critical thinking skills and deep engagement with the material.';
  } else if (total >= 7) {
    html += 'Great job! You show strong critical thinking abilities with room for further refinement.';
  } else if (total >= 5.5) {
    html += 'Good effort! You have a solid foundation. Continue practicing to strengthen your analytical skills.';
  } else {
    html += 'You are on the right track. Revisit the chapter concepts and try to apply them more deeply in your analysis.';
  }
  html += '</p>';
  
  html += '<p><strong>Dimension Breakdown:</strong></p><ul>';
  var dimNames = {
    clarity: 'Clarity', accuracy: 'Accuracy', logicalCorrectness: 'Logical Correctness',
    relevance: 'Relevance', completeness: 'Completeness', fairness: 'Fairness'
  };
  Object.keys(scores).forEach(function(dim) {
    var score = scores[dim];
    var name = dimNames[dim] || dim;
    var comment = '';
    if (score >= 8) comment = 'Excellent';
    else if (score >= 6) comment = 'Good';
    else if (score >= 4) comment = 'Developing';
    else comment = 'Needs work';
    html += '<li><strong>' + name + ':</strong> ' + score.toFixed(1) + '/10 — ' + comment + '</li>';
  });
  html += '</ul>';
  
  // Specific suggestions
  html += '<p><strong>Recommendations for Improvement:</strong></p><ul>';
  
  // Find weakest dimension
  var weakest = Object.keys(scores).reduce(function(a, b) { return scores[a] < scores[b] ? a : b; });
  var suggestions = {
    clarity: 'Work on structuring your report with clear topic sentences and smooth transitions between ideas.',
    accuracy: 'Incorporate more specific concepts and terminology from the chapter to demonstrate deep understanding.',
    logicalCorrectness: 'Use more indicator words and explicit reasoning chains. Make sure each claim has supporting reasons.',
    relevance: 'Make sure every paragraph directly relates to the core question. Cut tangential ideas.',
    completeness: 'Expand your knowledge map with more connections and add more depth to your report analysis.',
    fairness: 'Try to present multiple perspectives fairly before drawing your conclusion. Acknowledge counterarguments.'
  };
  
  html += '<li><strong>Focus on ' + (dimNames[weakest] || weakest) + ':</strong> ' + (suggestions[weakest] || 'Continue practicing this dimension.') + '</li>';
  html += '<li><strong>Iterate more:</strong> Each revision helps improve your work. Aim for 3-4 iterations.</li>';
  html += '<li><strong>Use fewer hints:</strong> Try to work through questions more independently before revealing hints — this strengthens your critical thinking muscles.</li>';
  
  html += '</ul>';
  html += '</div>';
  return html;
}

// ===== Step 6: Evaluation & Reflection =====
function renderPBLStep6(chKey, proj, data) {
  var hasScore = proj.aiScore !== null;
  var scoreData = hasScore ? null : null;
  
  var html = '';
  
  if (!hasScore) {
    html += '<div class="card"><div class="card-body" style="text-align:center; padding:40px 20px;">';
    html += '<div style="font-size:64px; margin-bottom:16px;">\u23f3</div>';
    html += '<h3 style="font-size:18px; margin-bottom:8px;">Awaiting Submission</h3>';
    html += '<p class="text-sm text-secondary mb-16">Submit your project in Step 5 to receive your AI evaluation.</p>';
    html += '<button class="btn btn-primary" onclick="goToPBLStep(5); document.querySelector(\'.content-area\').scrollTop = 0;">Go to Submit</button>';
    html += '</div></div>';
  } else {
    // Recalculate scores for display
    var scoreResult = calculatePBLAIScore(chKey, proj);
    var dimScores = scoreResult.scores || {};
    var scoreKeys = Object.keys(dimScores);
    var scoreValues = scoreKeys.map(function(k) { return dimScores[k]; });
    var scoreLabels = scoreKeys.map(function(k) {
      var map = {clarity:'Clarity',accuracy:'Accuracy',logicalCorrectness:'Logic',relevance:'Relevance',completeness:'Complete',fairness:'Fairness'};
      return map[k] || k;
    });
    
    html += '<div class="grid-2">';
    
    // Left: Radar + score
    html += '<div class="card"><div class="card-header"><div class="card-title">AI Evaluation Score</div></div><div class="card-body">';
    html += '<div class="eval-radar-section">';
    html += '<div class="eval-score-large">' + proj.aiScore.toFixed(1) + '</div>';
    html += '<div class="eval-score-label">out of 10</div>';
    
    // Mini radar
    var radarSvg = generateRadarSVG(scoreValues, scoreLabels);
    // Resize for this context - regenerate with smaller size
    var smallRadar = generateEvalRadar(scoreValues, scoreLabels);
    html += '<div style="margin-top:12px;">' + smallRadar + '</div>';
    html += '</div></div></div>';
    
    // Right: AI Feedback
    html += '<div class="card"><div class="card-header"><div class="card-title">AI Detailed Feedback</div></div><div class="card-body">';
    html += proj.aiFeedback;
    html += '</div></div>';
    
    html += '</div>'; // end grid-2
    
    // Iteration record
    html += '<div class="card mt-16"><div class="card-header"><div class="card-title">Iteration History</div>';
    html += '<span class="text-sm text-muted">' + (proj.iterations || 0) + ' iterations</span></div><div class="card-body">';
    
    var drafts = proj.reportDrafts || [];
    if (drafts.length === 0) {
      html += '<p class="text-sm text-muted">No iterations yet.</p>';
    } else {
      html += '<div class="iteration-timeline">';
      drafts.forEach(function(draft, idx) {
        var words = draft.text.trim() ? draft.text.trim().split(/\s+/).length : 0;
        var isLast = idx === drafts.length - 1;
        html += '<div class="iteration-item ' + (isLast ? 'current' : '') + '">';
        html += '<div class="iteration-version">Version ' + (idx + 1) + (isLast ? ' (Final)' : '') + '</div>';
        html += '<div class="iteration-date">' + new Date(draft.timestamp).toLocaleString() + '</div>';
        html += '<div class="iteration-change">' + words + ' words' + (idx > 0 ? ' | ' + (words - drafts[idx-1].text.trim().split(/\s+/).length > 0 ? (words - drafts[idx-1].text.trim().split(/\s+/).length) : 0) + ' words from previous' : '') + '</div>';
        html += '</div>';
      });
      html += '</div>';
    }
    html += '</div></div>';
    
    // Reflection
    html += '<div class="card mt-16"><div class="card-header"><div class="card-title">Self-Reflection</div></div><div class="card-body">';
    html += '<p class="text-sm text-secondary mb-12">Take a moment to reflect on your learning journey through this project.</p>';
    
    var refl = proj.reflection || { q1: '', q2: '', q3: '' };
    data.reflectionQuestions.forEach(function(q, qi) {
      html += '<div class="reflection-question">';
      html += '<label>Question ' + (qi + 1) + ': ' + q + '</label>';
      html += '<textarea id="refl_' + qi + '" placeholder="Write your reflection here..." onchange="saveReflection()">' + (refl['q' + (qi + 1)] || '') + '</textarea>';
      html += '</div>';
    });
    
    html += '<button class="btn btn-outline btn-sm" onclick="saveReflection()">Save Reflection</button>';
    html += '</div></div>';
    
    // Mark complete
    if (proj.status !== 'completed') {
      html += '<div class="pbl-action-bar">';
      html += '<button class="btn btn-outline" onclick="prevPBLStep()">&#8592; Back</button>';
      html += '<span class="text-sm text-muted">Step 6 of 6 — Evaluation</span>';
      html += '<button class="btn btn-success" onclick="markPBLComplete()">Mark as Complete</button>';
      html += '</div>';
    } else {
      html += '<div class="pbl-action-bar">';
      html += '<button class="btn btn-outline" onclick="navigateTo(\'pbl\')">&#8592; Back to Projects</button>';
      html += '<span class="text-sm text-success font-600">&#10003; Project Completed</span>';
      html += '<button class="btn btn-primary" onclick="navigateTo(\'dashboard\')">Go to Dashboard</button>';
      html += '</div>';
    }
  }
  
  return html;
}

function generateEvalRadar(scores, labels) {
  var size = 260;
  var cx = size / 2, cy = size / 2;
  var radius = 90;
  var n = scores.length;
  var angleStep = (2 * Math.PI) / n;
  var startAngle = -Math.PI / 2;
  var maxVal = 10;
  
  var gridPolygons = "";
  [2, 4, 6, 8, 10].forEach(function(level) {
    var r = (level / maxVal) * radius;
    var points = "";
    for (var i = 0; i < n; i++) {
      var angle = startAngle + i * angleStep;
      var x = cx + r * Math.cos(angle), y = cy + r * Math.sin(angle);
      points += x.toFixed(1) + "," + y.toFixed(1) + " ";
    }
    gridPolygons += '<polygon points="' + points + '" fill="none" stroke="#e0e6ed" stroke-width="1"/>';
  });
  
  var axisLines = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var x = cx + radius * Math.cos(angle), y = cy + radius * Math.sin(angle);
    axisLines += '<line x1="' + cx.toFixed(1) + '" y1="' + cy.toFixed(1) + '" x2="' + x.toFixed(1) + '" y2="' + y.toFixed(1) + '" stroke="#e0e6ed" stroke-width="1"/>';
  }
  
  var dataPoints = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var r = (scores[i] / maxVal) * radius;
    var x = cx + r * Math.cos(angle), y = cy + r * Math.sin(angle);
    dataPoints += x.toFixed(1) + "," + y.toFixed(1) + " ";
  }
  
  var labelTexts = "";
  for (var i = 0; i < n; i++) {
    var angle = startAngle + i * angleStep;
    var labelR = radius + 18;
    var x = cx + labelR * Math.cos(angle), y = cy + labelR * Math.sin(angle);
    var anchor = "middle";
    if (Math.cos(angle) > 0.3) anchor = "start";
    if (Math.cos(angle) < -0.3) anchor = "end";
    labelTexts += '<text x="' + x.toFixed(1) + '" y="' + y.toFixed(1) + '" text-anchor="' + anchor + '" dominant-baseline="middle" font-size="10" fill="#5a6c7d" font-weight="500">' + labels[i] + '</text>';
  }
  
  return '<svg viewBox="0 0 ' + size + ' ' + size + '" width="100%" style="max-width:280px; display:block; margin:0 auto;">' +
    gridPolygons + axisLines +
    '<polygon points="' + dataPoints + '" fill="rgba(52,152,219,0.25)" stroke="#3498db" stroke-width="2"/>' +
    labelTexts + '</svg>';
}

function saveReflection() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (!proj.reflection) proj.reflection = { q1: '', q2: '', q3: '' };
  
  for (var i = 1; i <= 3; i++) {
    var el = document.getElementById('refl_' + (i - 1));
    if (el) proj.reflection['q' + i] = el.value;
  }
  
  savePBLProject(chKey);
  
  var btn = event && event.target;
  if (btn) {
    var orig = btn.textContent;
    btn.textContent = 'Saved!';
    setTimeout(function() { btn.textContent = orig; }, 1000);
  }
}

function markPBLComplete() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  proj.status = 'completed';
  savePBLProject(chKey);
  
  // Update capstone milestone status
  var s = AppState.student;
  if (s.capstoneProjectId && s.milestones && s.milestones[chKey]) {
    s.milestones[chKey].status = 'completed';
    s.milestones[chKey].completedAt = Date.now();
    // Save final report as milestone deliverable
    s.milestones[chKey].deliverable = proj.finalReport || '';
    saveStudent();
  }
  
  addMessage({
    type: 'success',
    title: 'PBL Project Complete!',
    body: 'Congratulations on completing the ' + getPBLDisplayData(chKey).title + ' project! Your work has been added to your portfolio.'
  });
  
  // Refresh
  var data = getPBLDisplayData(chKey);
  var content = document.getElementById('pblStepContent');
  if (content) {
    content.innerHTML = renderPBLStep6(chKey, proj, data);
  }
  updateTopProgress();
}

function nextPBLStep() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (proj.currentStep < 6) {
    proj.currentStep++;
    savePBLProject(chKey);
  }
  renderPBLDetail(document.getElementById('contentArea'));
  // Reset scroll
  document.querySelector('.content-area').scrollTop = 0;
}

function prevPBLStep() {
  var chKey = PBL_CURRENT_PROJECT;
  var proj = getPBLProject(chKey);
  if (proj.currentStep > 1) {
    proj.currentStep--;
    savePBLProject(chKey);
  }
  renderPBLDetail(document.getElementById('contentArea'));
  document.querySelector('.content-area').scrollTop = 0;
}



