function resetAllProgress() {
  if (confirm("Reset ALL progress for this student? This will delete all quiz results, PBL work, and messages.")) {
    var sid = v7GetCurrentStudentId();
    if (sid) {
      var dataKey = v7GetStudentDataKey(sid);
      localStorage.removeItem(dataKey);
      localStorage.removeItem(dataKey + "_messages");
      localStorage.removeItem(dataKey + "_ai_conv");
    }
    localStorage.removeItem("ctp_student");
    localStorage.removeItem("ctp_messages");
    localStorage.removeItem("ctp_ai_conversation");
    location.reload();
  }
}


