async function getFeishuTenantToken(config) {
  var url = 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal';
  var resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    body: JSON.stringify({ app_id: config.app_id, app_secret: config.app_secret })
  });
  var data = await resp.json();
  if (data.code !== 0) {
    throw new Error('Failed to get tenant token: ' + (data.msg || data.code));
  }
  return data.tenant_access_token;
}

function buildBitableFields(exportData) {
  var info = exportData.studentInfo || {};
  var chaptersCompleted = exportData.chaptersCompleted || {};
  var completedCount = 0;
  for (var k in chaptersCompleted) {
    if (chaptersCompleted.hasOwnProperty(k) && chaptersCompleted[k]) completedCount++;
  }

  var fields = {};
  fields['学生ID'] = info.studentId || '';
  fields['学生姓名'] = info.name || '';
  fields['学号'] = info.studentId || '';
  fields['邮箱'] = info.email || '';
  fields['班级'] = info.classCode || '';
  fields['预测试分数'] = exportData.pretest && exportData.pretest.score != null ? exportData.pretest.score : 0;
  fields['后测试分数'] = exportData.posttest && exportData.posttest.score != null ? exportData.posttest.score : 0;
  fields['完成章节数'] = completedCount;
  fields['各章节成绩(JSON)'] = JSON.stringify(exportData.chapterScores || {});
  fields['PBL项目(JSON)'] = JSON.stringify(exportData.pblProjects || {});
  fields['维度得分(JSON)'] = JSON.stringify(exportData.dimensionScores || {});
  fields['AI对话记录(JSON)'] = JSON.stringify(exportData.aiConversations || []);
  fields['讨论发帖(JSON)'] = JSON.stringify(exportData.discussionPosts || []);
  fields['完整数据JSON'] = JSON.stringify(exportData);
  fields['最后更新时间'] = new Date().toISOString();

  return fields;
}

async function searchBitableRecord(token, baseToken, tableId, studentId) {
  var url = 'https://open.feishu.cn/open-apis/bitable/v1/apps/' + baseToken + '/tables/' + tableId + '/records/search?page_size=1';
  var resp = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Authorization': 'Bearer ' + token
    },
    body: JSON.stringify({
      filter: {
        conjunction: 'and',
        conditions: [
          { field_name: '学生ID', operator: 'is', value: [studentId] }
        ]
      }
    })
  });
  var data = await resp.json();
  if (data.code !== 0) {
    throw new Error('Search failed: ' + (data.msg || data.code));
  }
  var items = data.data && data.data.items ? data.data.items : [];
  return items.length > 0 ? items[0] : null;
}

async function createBitableRecord(token, baseToken, tableId, fields) {
  var url = 'https://open.feishu.cn/open-apis/bitable/v1/apps/' + baseToken + '/tables/' + tableId + '/records';
  var resp = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Authorization': 'Bearer ' + token
    },
    body: JSON.stringify({ fields: fields })
  });
  var data = await resp.json();
  if (data.code !== 0) {
    throw new Error('Create record failed: ' + (data.msg || data.code));
  }
  return data.data;
}

async function updateBitableRecord(token, baseToken, tableId, recordId, fields) {
  var url = 'https://open.feishu.cn/open-apis/bitable/v1/apps/' + baseToken + '/tables/' + tableId + '/records/' + recordId;
  var resp = await fetch(url, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'Authorization': 'Bearer ' + token
    },
    body: JSON.stringify({ fields: fields })
  });
  var data = await resp.json();
  if (data.code !== 0) {
    throw new Error('Update record failed: ' + (data.msg || data.code));
  }
  return data.data;
}

