function buildExportData() {
  var s = AppState.student;
  if (!s) return null;

  // Collect chapter scores
  var chapterScores = {};
  for (var i = 1; i <= 10; i++) {
    var chKey = 'ch' + i;
    chapterScores[chKey] = s.chapterScores && s.chapterScores[chKey] != null ? s.chapterScores[chKey] : 0;
  }

  // AI conversation history
  var aiConversations = [];
  try {
    if (typeof AI_TUTOR_STATE !== 'undefined' && AI_TUTOR_STATE.conversation) {
      aiConversations = AI_TUTOR_STATE.conversation;
    }
  } catch(e) {}

  // Student info
  var studentInfo = {
    name: s.name || '',
    studentId: s.id || s.studentId || '',
    classCode: s.classCode || '',
    email: s.email || ''
  };

  // Pretest
  var pretest = {
    score: s.pretestScore != null ? s.pretestScore : null,
    taken: s.pretestTaken || false,
    date: s.pretestDate || null
  };

  // Posttest
  var posttest = {
    score: s.posttestScore != null ? s.posttestScore : null,
    taken: s.posttestTaken || false,
    date: s.posttestDate || null
  };

  // Milestones
  var milestones = {};
  if (s.milestones) {
    milestones = s.milestones;
  } else if (s.pblProjects) {
    for (var mk in s.pblProjects) {
      if (s.pblProjects.hasOwnProperty(mk)) {
        milestones[mk] = {
          status: s.pblProjects[mk].status || 'not_started',
          completedAt: s.pblProjects[mk].submittedAt || null
        };
      }
    }
  }

  // Discussion posts by this student
  var discussionPosts = [];
  try {
    var allPosts = getAllForumPostsForStudent(s.id || s.name);
    discussionPosts = allPosts;
  } catch(e) {}

  var exportData = {
    studentInfo: studentInfo,
    chaptersCompleted: s.chaptersCompleted || {},
    chapterScores: chapterScores,
    pblProjects: s.pblProjects || {},
    milestones: milestones,
    pretest: pretest,
    posttest: posttest,
    questionHistory: s.questionHistory || [],
    dimensionScores: s.dimensionScores || {},
    dimensionAttempts: s.dimensionAttempts || {},
    practiceSessions: s.practiceSessions || 0,
    streak: s.streak || 0,
    aiConversations: aiConversations,
    discussionPosts: discussionPosts,
    recommendations: s.recommendations || [],
    currentDifficulty: s.currentDifficulty || 'basic',
    lastActivity: s.lastActivity || null,
    exportDate: new Date().toISOString(),
    version: 'v14'
  };

  return exportData;
}

function exportStudentData() {
  var data = buildExportData();
  if (!data) {
    alert('No student data to export.');
    return;
  }

  var namePart = (data.studentInfo.name || 'student').replace(/[^a-zA-Z0-9_]/g, '_');
  var idPart = (data.studentInfo.studentId || 'unknown').replace(/[^a-zA-Z0-9_]/g, '_');
  var datePart = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  var filename = 'critical_thinking_' + idPart + '_' + namePart + '_' + datePart + '.json';

  var jsonStr = JSON.stringify(data, null, 2);
  var blob = new Blob([jsonStr], { type: 'application/json' });
  var url = URL.createObjectURL(blob);

  var a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  showToast('Learning data exported successfully!', 'success');
}

function importStudentData(file) {
  if (!file) return;

  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      var data = JSON.parse(e.target.result);

      if (!data.studentInfo) {
        alert('Invalid file format: Missing studentInfo.');
        return;
      }

      // Verify this is the same student
      var s = AppState.student;
      var currentName = s ? s.name : '';
      var currentId = s ? (s.id || s.studentId || '') : '';
      var importName = data.studentInfo.name || '';
      var importId = data.studentInfo.studentId || '';

      var confirmMsg = 'Import data for:\n\n  Name: ' + importName +
        '\n  Student ID: ' + importId +
        '\n\nThis will REPLACE all your current learning data. Continue?';

      if (currentName && currentName !== importName && currentId && currentId !== importId) {
        confirmMsg = 'WARNING: Imported data is for a different student!\n\n' +
          'Current: ' + currentName + ' (' + currentId + ')\n' +
          'Imported: ' + importName + ' (' + importId + ')\n\n' +
          'Importing will REPLACE your current data. Are you sure?';
      }

      if (!confirm(confirmMsg)) return;

      // Merge / replace data
      if (data.chaptersCompleted) s.chaptersCompleted = data.chaptersCompleted;
      if (data.chapterScores) s.chapterScores = data.chapterScores;
      if (data.pblProjects) s.pblProjects = data.pblProjects;
      if (data.pretest) {
        s.pretestScore = data.pretest.score != null ? data.pretest.score : s.pretestScore;
        s.pretestTaken = data.pretest.taken != null ? data.pretest.taken : s.pretestTaken;
      }
      if (data.posttest) {
        s.posttestScore = data.posttest.score != null ? data.posttest.score : s.posttestScore;
        s.posttestTaken = data.posttest.taken != null ? data.posttest.taken : s.posttestTaken;
      }
      if (data.questionHistory) s.questionHistory = data.questionHistory;
      if (data.dimensionScores) s.dimensionScores = data.dimensionScores;
      if (data.dimensionAttempts) s.dimensionAttempts = data.dimensionAttempts;
      if (data.practiceSessions != null) s.practiceSessions = data.practiceSessions;
      if (data.streak != null) s.streak = data.streak;
      if (data.recommendations) s.recommendations = data.recommendations;
      if (data.currentDifficulty) s.currentDifficulty = data.currentDifficulty;
      if (data.lastActivity) s.lastActivity = data.lastActivity;

      // Save AI conversations
      if (data.aiConversations && typeof AI_TUTOR_STATE !== 'undefined') {
        AI_TUTOR_STATE.conversation = data.aiConversations;
      }

      // Save everything
      saveStudent();
      saveMessages();
      if (typeof saveAIV7 === 'function') {
        saveAIV7();
      }

      // Refresh UI
      updateStudentInfoUI();
      if (AppState.currentPage === 'dashboard') {
        renderDashboard(document.getElementById('contentArea'));
      } else {
        navigateTo('dashboard');
      }

      showToast('Data imported successfully!', 'success');

    } catch(err) {
      alert('Import failed: ' + err.message);
    }
  };
  reader.readAsText(file);
}

