// Helper: toast notification
function showToast(message, type) {
  type = type || 'info';
  var toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;top:20px;right:20px;padding:12px 20px;background:' +
    (type === 'success' ? '#27ae60' : type === 'error' ? '#e74c3c' : '#3498db') +
    ';color:#fff;border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,0.15);z-index:10000;' +
    'font-size:13px;font-weight:500;animation:slideInRight 0.3s ease;';
  toast.textContent = message;
  document.body.appendChild(toast);
  setTimeout(function() { toast.style.opacity = '0'; toast.style.transition = 'opacity 0.3s'; }, 2200);
  setTimeout(function() { if (toast.parentNode) toast.parentNode.removeChild(toast); }, 2600);
}

// Helper: get forum posts for a student (best-effort)
function getAllForumPostsForStudent(studentIdOrName) {
  try {
    if (typeof FORUM_DATA !== 'undefined' && FORUM_DATA.posts) {
      return FORUM_DATA.posts.filter(function(p) {
        return p.authorId === studentIdOrName || p.author === studentIdOrName;
      });
    }
  } catch(e) {}
  return [];
}


